    /** 登记窗口；version 为同赞助商内顺序版本，返回窗口自增 ID。 */
    public long insertSponsorWindow(String sponsorKey, LocalDate businessDay, long version,
                                    long startMs, long endMs, long createdAtMs) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO playout_sponsor_window"
                            + " (sponsor_key, business_day, version, start_ms, end_ms, status,"
                            + "  created_at_ms)"
                            + " VALUES (?, ?, ?, ?, ?, 'ACTIVE', ?)", Statement.RETURN_GENERATED_KEYS);
