    /**
     * 同赞助商、状态 ACTIVE、与频道集合中任一频道关联且与 [startMs, endMs) 时间相交的窗口，
     * 加行锁。须在按升序锁定全部相关频道行后调用，与窗口登记/删除及发布事务串行。
     */
    public List<SponsorWindowRow> findOverlappingSponsorWindowsForUpdate(
            String sponsorKey, long startMs, long endMs, List<String> channelIds) {
        String placeholders = String.join(",", channelIds.stream().map(c -> "?").toList());
        return jdbc.query("SELECT w.id, w.sponsor_key, w.business_day, w.version, w.start_ms,"
