                        + " FROM playout_sponsor_window w"
                        + " WHERE w.sponsor_key = ? AND w.status = 'ACTIVE'"
                        + " AND w.start_ms < ? AND w.end_ms > ?"
                        + " AND EXISTS (SELECT 1 FROM playout_sponsor_window_channel wc"
                        + " WHERE wc.window_id = w.id AND wc.channel_id IN (" + placeholders + "))"
                        + " ORDER BY w.id FOR UPDATE",
                ps -> {
                    ps.setString(1, sponsorKey);
                    ps.setLong(2, endMs);
                    ps.setLong(3, startMs);
                    for (int i = 0; i < channelIds.size(); i++) {
                        ps.setString(4 + i, channelIds.get(i));
                    }
                }, SPONSOR_WINDOW_MAPPER);
    }

