        return jdbc.query("SELECT id, publication_id, segment_id, asset_id, sponsor_key, window_id,"
                        + " window_version, start_ms, end_ms"
                        + " FROM playout_publication_sponsor_hit"
                        + " WHERE publication_id = ? ORDER BY start_ms, segment_id, window_id",
