/**
 * 播出编排核心服务：素材、频道、授权、草稿、发布、播出决定、紧急插播与赞助商排他。
 *
 * <p>约定：数据库内时间统一为 UTC 纪元毫秒；API 边界统一为 Asia/Shanghai、毫秒精度 ISO 8601；
 * 业务日为 Asia/Shanghai 日历日。授权区间、排他窗与素材时段均左闭右开。所有写操作与幂等去重记录
 * 在同一事务提交，失败整体回滚、不占用 requestId。</p>
 *
 * <p>赞助商排他：素材可关联 sponsorKey（null 为无赞助商）；运营日登记的 ACTIVE 排他窗命中间频道
 * 范围与 UTC 时段。发布草稿或紧急插播前在持频道锁后校验素材授权、既有 ACTIVE 插播占位与所有命中
 * 排他窗的完整最终编排；异赞助商冲突整次 409，多频道发布不留下部分更新。发布固化窗口版本与素材
 * sponsorKey，窗口之后删除/修订不改写快照。</p>
 */
@Service
public class PlayoutService {

    /** 业务时区。 */
    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private static final String OP_REPLACE_DRAFT = "REPLACE_DRAFT";
    private static final String OP_PUBLISH = "PUBLISH";
    private static final String OP_PUBLISH_BATCH = "PUBLISH_BATCH";
    private static final String OP_REVOKE_GRANT = "REVOKE_GRANT";
    private static final String OP_CREATE_OVERRIDE = "CREATE_OVERRIDE";
    private static final String OP_CANCEL_OVERRIDE = "CANCEL_OVERRIDE";
    private static final String OP_REGISTER_WINDOW = "REGISTER_SPONSOR_WINDOW";
    private static final String OP_CANCEL_WINDOW = "CANCEL_SPONSOR_WINDOW";
    private static final String OP_CANCEL_PUBLICATION = "CANCEL_PUBLICATION";

    /** 紧急插播时长上限（含）：30 分钟，单位毫秒。 */
    private static final long OVERRIDE_MAX_DURATION_MS = 30L * 60L * 1000L;

    private final PlayoutRepository repo;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public PlayoutService(PlayoutRepository repo, ObjectMapper objectMapper, Clock clock) {
        this.repo = repo;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    // ---------- 素材 ----------

    /** 创建素材；id 为空时生成稳定 ID；sponsorKey 空白视为无赞助商素材。 */
    @Transactional
    public AssetResponse createAsset(CreateAssetRequest request) {
        String id = request.id() == null || request.id().isBlank()
                ? UUID.randomUUID().toString() : request.id();
        String sponsorKey = normalizeSponsorKey(request.sponsorKey());
        try {
            repo.insertAsset(id, request.durationMs(), sponsorKey, nowMs());
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("DUPLICATE_ID", "素材 ID 已存在: " + id);
        }
        return new AssetResponse(id, request.durationMs(), sponsorKey);
    }

    // ---------- 频道 ----------

    /** 创建频道，保底素材必须已存在且不会被撤销。 */
    @Transactional
    public ChannelResponse createChannel(CreateChannelRequest request) {
        String id = request.id() == null || request.id().isBlank()
                ? UUID.randomUUID().toString() : request.id();
        if (repo.findAsset(request.fallbackAssetId()).isEmpty()) {
            throw ApiException.notFound("保底素材不存在: " + request.fallbackAssetId());
        }
        try {
            repo.insertChannel(id, request.fallbackAssetId(), nowMs());
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("DUPLICATE_ID", "频道 ID 已存在: " + id);
        }
        return new ChannelResponse(id, request.fallbackAssetId());
    }

    // ---------- 授权 ----------

    /** 创建授权，关联频道与普通素材，有效区间左闭右开。 */
    @Transactional
    public GrantResponse createGrant(CreateGrantRequest request) {
        var channel = repo.findChannel(request.channelId())
                .orElseThrow(() -> ApiException.notFound("频道不存在: " + request.channelId()));
        if (repo.findAsset(request.assetId()).isEmpty()) {
            throw ApiException.notFound("素材不存在: " + request.assetId());
        }
        long fromMs = toMs(request.validFrom());
        long toMs = toMs(request.validTo());
        if (toMs <= fromMs) {
            throw ApiException.badRequest("授权有效区间终点必须大于起点");
        }
        if (channel.fallbackAssetId().equals(request.assetId())) {
            throw ApiException.unprocessable("FALLBACK_ASSET_NOT_GRANTABLE",
                    "保底素材无需授权，不能对其创建授权");
        }
        long id = repo.insertGrant(request.channelId(), request.assetId(), fromMs, toMs, nowMs());
        return new GrantResponse(id, request.channelId(), request.assetId(),
                request.validFrom(), request.validTo(), false);
    }

    /** 撤销授权；幂等：同 requestId 同参数返回原结果，改参数返回 409。 */
    @Transactional
    public GrantResponse revokeGrant(long grantId, String requestId) {
        String hash = sha256(OP_REVOKE_GRANT + "|" + grantId);
        return idempotent(requestId, OP_REVOKE_GRANT, hash, GrantResponse.class, () -> {
            GrantRow grant = repo.findGrant(grantId)
                    .orElseThrow(() -> ApiException.notFound("授权不存在: " + grantId));
            int updated = repo.revokeGrant(grantId, requestId, nowMs());
            if (updated == 0) {
                throw ApiException.conflict("GRANT_ALREADY_REVOKED", "授权已撤销: " + grantId);
            }
            return new GrantResponse(grant.id(), grant.channelId(), grant.assetId(),
                    atMs(grant.validFromMs()), atMs(grant.validToMs()), true);
        });
    }

    // ---------- 草稿 ----------

    /** 整份替换草稿；携带 expectedDraftVersion（0 表示首次创建），版本不符返回 409 且不改写原草稿。 */
    @Transactional
    public DraftResponse replaceDraft(String channelId, LocalDate businessDay,
                                      ReplaceDraftRequest request) {
        repo.findChannel(channelId)
                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));

        String hash = sha256(OP_REPLACE_DRAFT + "|" + channelId + "|" + businessDay
                + "|" + request.expectedDraftVersion() + "|" + canonicalSegments(request.segments()));
        return idempotent(request.requestId(), OP_REPLACE_DRAFT, hash, DraftResponse.class, () -> {
            List<ValidatedSegment> segments = validateSegments(channelId, businessDay, request.segments());
            long newVersion;
            if (request.expectedDraftVersion() == 0) {
                try {
                    repo.insertDraft(channelId, businessDay, nowMs());
                } catch (DuplicateKeyException e) {
                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
                            "草稿已存在，expectedDraftVersion 不能为 0");
                }
                newVersion = 1;
            } else {
                int updated = repo.bumpDraftVersion(channelId, businessDay,
                        request.expectedDraftVersion(), nowMs());
                if (updated == 0) {
                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
                            "草稿版本不符，期望 " + request.expectedDraftVersion());
                }
                newVersion = request.expectedDraftVersion() + 1;
            }
            repo.deleteDraftSegments(channelId, businessDay);
            for (ValidatedSegment segment : segments) {
                repo.insertDraftSegment(segment.id(), channelId, businessDay,
                        segment.assetId(), segment.startMs(), segment.endMs());
            }
            return new DraftResponse(channelId, businessDay.toString(), newVersion,
                    segments.stream().map(ValidatedSegment::toResponse).toList());
        });
    }

    // ---------- 发布 ----------

    /**
     * 发布草稿：在频道锁后校验草稿版本与发布版本，逐片段加锁校验授权仍有效，并在完整最终编排
     * （本次片段 + 既有 ACTIVE 紧急插播占位 + 全部命中 ACTIVE 排他窗）上校验赞助商排他；
     * 全部通过后原子生成只读快照并固化窗口命中。与授权撤销、窗口登记、插播创建并发时按数据库
     * 提交顺序生效。
     */
    @Transactional
    public PublishResponse publish(String channelId, LocalDate businessDay, PublishRequest request) {
        repo.findChannel(channelId)
                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));

        String hash = sha256(OP_PUBLISH + "|" + channelId + "|" + businessDay
                + "|" + request.draftVersion() + "|" + request.expectedPublishedVersion());
        return idempotent(request.requestId(), OP_PUBLISH, hash, PublishResponse.class, () -> {
            PublishChannelResult result = publishChannels(businessDay, List.of(
                    new PublishChannelInput(channelId, request.draftVersion(),
                            request.expectedPublishedVersion()))).get(0);
            return new PublishResponse(result.publicationId(), channelId, businessDay.toString(),
                    result.publishedVersion(), result.draftVersion());
        });
    }

    /**
     * 多频道批量发布：先按频道 ID 升序锁定并在完整最终编排上校验全部频道（授权、既有占位、
     * 命中排他窗、版本），任一频道异赞助冲突整次 409，全部快照与命中在同一事务内提交。
     */
    @Transactional
    public PublishBatchResponse publishBatch(LocalDate businessDay, PublishBatchRequest request) {
        String hash = sha256(OP_PUBLISH_BATCH + "|" + businessDay + "|"
                + canonicalChannelInputs(request.channels()));
        return idempotent(request.requestId(), OP_PUBLISH_BATCH, hash,
                PublishBatchResponse.class,
                () -> {
                    List<PublishChannelResult> results = publishChannels(businessDay, request.channels());
                    long totalDuration = results.stream()
                            .mapToLong(PublishChannelResult::scheduledDurationMs).sum();
                    return new PublishBatchResponse(businessDay.toString(),
                            request.channels().size(), results.size(), totalDuration, results);
                });
    }

    /** 批量发布共享实现：频道按 ID 升序处理以保证多事务交锁顺序一致。 */
    private List<PublishChannelResult> publishChannels(LocalDate businessDay,
                                                       List<PublishChannelInput> inputs) {
        List<String> duplicateChannels = inputs.stream()
                .collect(Collectors.groupingCount(PublishChannelInput::channelId)).stream()
                .filter(e -> e.getValue() > 1).map(Map.Entry::getKey).sorted().toList();
        if (!duplicateChannels.isEmpty()) {
            throw ApiException.badRequest("同一发布请求中频道重复: " + duplicateChannels);
        }
        List<PublishChannelInput> ordered = inputs.stream()
                .sorted(Comparator.comparing(PublishChannelInput::channelId))
                .toList();

        // 阶段一：锁定全部频道行，与窗口登记、紧急插播、其他发布按提交顺序串行。
        for (PublishChannelInput input : ordered) {
            repo.findChannel(input.channelId())
                    .orElseThrow(() -> ApiException.notFound("频道不存在: " + input.channelId()));
            repo.lockChannelForUpdate(input.channelId());
        }

        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();

        // 阶段二：在锁后读取完整最终态并校验，收集结果，先不写入。
        List<ChannelPublishPlan> plans = new ArrayList<>();
        List<Conflict> allConflicts = new ArrayList<>();
        for (PublishChannelInput input : ordered) {
            ChannelPublishPlan plan = prepareChannelPublish(input.channelId(), businessDay,
                    dayStartMs, dayEndMs, input.draftVersion(), input.expectedPublishedVersion());
            plans.add(plan);
            allConflicts.addAll(plan.conflicts());
        }
        if (!allConflicts.isEmpty()) {
            throw ApiException.sponsorConflict(toConflictDtos(allConflicts));
        }

        // 阶段三：全部校验通过后在同一事务内顺序提交所有频道快照。
        List<PublishChannelResult> results = new ArrayList<>();
        for (ChannelPublishPlan plan : plans) {
            results.add(commitChannelPublish(plan, businessDay));
        }
        return results;
    }

    /** 单个频道的锁后校验与发布数据准备（不写入）。 */
    private ChannelPublishPlan prepareChannelPublish(String channelId, LocalDate businessDay,
                                                     long dayStartMs, long dayEndMs,
                                                     long expectedDraftVersion,
                                                     long expectedPublishedVersion) {
        DraftRow draft = repo.findDraft(channelId, businessDay)
                .orElseThrow(() -> ApiException.notFound(
                        "草稿不存在: " + channelId + " " + businessDay));
        List<SegmentRow> segments = repo.findDraftSegments(channelId, businessDay);
        if (draft.version() != expectedDraftVersion) {
            throw ApiException.conflict("DRAFT_VERSION_CONFLICT", "草稿版本不符，当前 " + draft.version());
        }
        long currentPublished = repo.currentPublishedVersion(channelId, businessDay);
        if (currentPublished != expectedPublishedVersion) {
            throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
                    "发布版本冲突，当前 " + currentPublished);
        }

        List<Item> items = new ArrayList<>();
        List<Long> grantIds = new ArrayList<>();
        long scheduledDurationMs = 0L;
        for (SegmentRow segment : segments) {
            GrantRow grant = selectCoveringGrantForUpdate(channelId, segment);
            grantIds.add(grant.id());
            AssetRow asset = repo.findAsset(segment.assetId())
                    .orElseThrow(() -> ApiException.notFound("素材不存在: " + segment.assetId()));
            items.add(new Item(segment.id(), segment.assetId(), asset.sponsorKey(),
                    segment.startMs(), segment.endMs(), true));
            scheduledDurationMs += segment.endMs() - segment.startMs();
        }

        // 既有 ACTIVE 紧急插播为独立于草稿的生效占位（左闭右开，加载整日并锁行）。
        List<OverrideRow> overrides =
                repo.findAllActiveOverlappingForUpdate(channelId, dayStartMs, dayEndMs);
        for (OverrideRow override : overrides) {
            items.add(new Item(override.overrideKey(), override.assetId(), override.sponsorKey(),
                    override.startMs(), override.endMs(), false));
        }

        List<Window> windows = repo.findActiveWindowsForChannelForUpdate(
                        channelId, businessDay, dayStartMs, dayEndMs).stream()
                .map(PlayoutService::toWindow).toList();

        List<Conflict> conflicts = SponsorExclusivity.evaluateChannel(channelId, items, windows);
        return new ChannelPublishPlan(channelId, draft.version(), currentPublished + 1,
                segments, grantIds, windows, conflicts, scheduledDurationMs);
    }

    /** 写入单个频道快照：发布行、片段（固化 sponsorKey）与命中窗口历史。 */
    private PublishChannelResult commitChannelPublish(ChannelPublishPlan plan, LocalDate businessDay) {
        long publicationId;
        try {
            publicationId = repo.insertPublication(plan.channelId(), businessDay,
                    plan.newPublishedVersion(), plan.draftVersion(), nowMs());
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
                    "发布版本冲突，版本 " + plan.newPublishedVersion() + " 已存在");
        }
        for (int i = 0; i < plan.segments().size(); i++) {
            SegmentRow segment = plan.segments().get(i);
            AssetRow asset = repo.findAsset(segment.assetId()).orElseThrow();
            repo.insertPublicationSegment(publicationId, segment.id(), segment.assetId(),
                    asset.sponsorKey(), plan.grantIds().get(i), segment.startMs(), segment.endMs());
            // 固化命中：与片段相交且同赞助商的 ACTIVE 窗口逐窗记录版本。
            for (Window window : plan.windows()) {
                if (window.sponsorKey().equals(asset.sponsorKey())
                        && SponsorExclusivity.overlaps(segment.startMs(), segment.endMs(),
                        window.startMs(), window.endMs())) {
                    repo.insertSponsorHit(publicationId, segment.id(), segment.assetId(),
                            asset.sponsorKey(), window.id(), window.version(),
                            window.startMs(), window.endMs());
                }
            }
        }
        return new PublishChannelResult(plan.channelId(), publicationId, plan.newPublishedVersion(),
                plan.draftVersion(), plan.segments().size(), plan.scheduledDurationMs());
    }

    /**
     * 撤销尚未开始的发布：置快照为 CANCELLED 以释放占位（之后播出决定回到上一版 PUBLISHED 快照
     * 或保底），片段与窗口命中历史保留。已有片段开播（start &lt;= 当前时刻）时只能走紧急插播流程，
     * 返回 409。幂等：同 requestId 同参数返回首次结果。
     */
    @Transactional
    public PublicationDetailResponse cancelPublication(long publicationId, String requestId) {
        String hash = sha256(OP_CANCEL_PUBLICATION + "|" + publicationId);
        return idempotent(requestId, OP_CANCEL_PUBLICATION, hash,
                PublicationDetailResponse.class, () -> {
                    PublicationRow publication = repo.findPublicationByIdForUpdate(publicationId)
                            .orElseThrow(() -> ApiException.notFound("发布不存在: " + publicationId));
                    if (!publication.published()) {
                        throw ApiException.conflict("PUBLICATION_ALREADY_CANCELLED",
                                "发布已撤销: " + publicationId);
                    }
                    long now = nowMs();
                    int updated = repo.cancelPublication(publicationId, requestId, now, now);
                    if (updated == 0) {
                        throw ApiException.conflict("PUBLICATION_ALREADY_STARTED",
                                "发布已有片段开播，不能撤销，只能按紧急插播流程处理: " + publicationId);
                    }
                    return getPublicationDetail(publicationId);
                });
    }

    /** 查询发布快照明细（含片段、固化 sponsorKey、窗口命中历史与撤销情况），查询不改变状态。 */
    @Transactional(readOnly = true)
    public PublicationDetailResponse getPublicationDetail(long publicationId) {
        PublicationRow publication = repo.findPublicationByIdForUpdate(publicationId)
                .orElseThrow(() -> ApiException.notFound("发布不存在: " + publicationId));
        return toPublicationDetail(publication,
                repo.findPublicationSegments(publicationId),
                repo.findSponsorHits(publicationId));
    }

    // ---------- 播出决定 ----------

    /**
     * 按频道与时刻查询播出决定。先在命中该时刻的 ACTIVE 紧急插播中选取指定授权当前未撤销的
     * 最高优先级插播（EMERGENCY 来源，随附 overrideKey）；高优先级插播授权失效时自动落到
     * 仍有效的低优先级插播。无有效插播候选时沿用原节目与保底逻辑（已撤销发布不生效，回落到
     * 上一版 PUBLISHED 快照）。查询不改变插播状态，插播不随授权撤销自动换绑授权。
     * 到插播结束时刻（左闭右开）不再命中。
     */
    @Transactional(readOnly = true)
    public PlayoutDecisionResponse playoutDecision(String channelId, OffsetDateTime at) {
        var channel = repo.findChannel(channelId)
                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
        long atMs = toMs(at);

        Optional<OverrideRow> override = selectActiveOverrideAt(channelId, atMs);
        if (override.isPresent()) {
            OverrideRow hit = override.get();
            return new PlayoutDecisionResponse(channelId, at, hit.assetId(),
                    DecisionSource.EMERGENCY, null, null, null, hit.overrideKey());
        }

        LocalDate businessDay = at.atZoneSameInstant(ZONE).toLocalDate();

        Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
        if (publication.isEmpty()) {
            return fallback(channelId, at, channel.fallbackAssetId(),
                    FallbackReason.NO_PUBLISHED_SCHEDULE);
        }
        Optional<PublicationSegmentRow> segment =
                repo.findPublicationSegmentAt(publication.get().id(), atMs);
        if (segment.isEmpty()) {
            return fallback(channelId, at, channel.fallbackAssetId(),
                    FallbackReason.GAP);
        }
        PublicationSegmentRow hit = segment.get();
        GrantRow grant = repo.findGrant(hit.grantId())
                .orElseThrow(() -> ApiException.unprocessable("SNAPSHOT_INCOMPLETE",
                        "发布快照引用的授权不存在: " + hit.grantId()));
        if (grant.revoked()) {
            return new PlayoutDecisionResponse(channelId, at, channel.fallbackAssetId(),
                    DecisionSource.FALLBACK,
                    FallbackReason.GRANT_REVOKED,
                    publication.get().id(), hit.segmentId(), null);
        }
        return new PlayoutDecisionResponse(channelId, at, hit.assetId(),
                DecisionSource.PROGRAM, null,
                publication.get().id(), hit.segmentId(), null);
    }

    /**
     * 选取某时刻生效的最高优先级紧急插播：候选为区间命中且 ACTIVE 的插播，按优先级降序，
     * 跳过其指定授权已撤销的插播。授权状态为查询时的实时状态。
     */
    private Optional<OverrideRow> selectActiveOverrideAt(String channelId, long atMs) {
        for (OverrideRow candidate : repo.findActiveOverridesAt(channelId, atMs)) {
            GrantRow grant = repo.findGrant(candidate.grantId()).orElse(null);
            if (grant != null && !grant.revoked()) {
                return Optional.of(candidate);
            }
        }
        return Optional.empty();
    }

    // ---------- 紧急插播 ----------

    /**
     * 创建限时紧急插播：创建即 ACTIVE，只可取消不可改写。校验频道/素材/授权存在、授权属于该
     * 频道与素材且未撤销并完整覆盖区间、区间同日且时长在 (0, 30 分钟]；同频道同优先级 ACTIVE
     * 区间不得重叠（相邻合法）。在频道锁后还要在完整最终编排（既有 ACTIVE 插播、最新 PUBLISHED
     * 快照占位与全部命中排他窗）上校验赞助商排他，异赞助冲突 409。携带 requestId 幂等：
     * 同键同参返回首次结果，改参 409，失败不占键；已取消插播不能用相同 overrideKey 重放复活。
     */
    @Transactional
    public EmergencyOverrideResponse createEmergencyOverride(CreateEmergencyOverrideRequest request) {
        String hash = sha256(OP_CREATE_OVERRIDE + "|" + request.overrideKey() + "|"
                + request.channelId() + "|" + request.assetId() + "|" + request.grantId() + "|"
                + request.priority() + "|" + toMs(request.start()) + "|" + toMs(request.end()));
        return idempotent(request.requestId(), OP_CREATE_OVERRIDE, hash,
                EmergencyOverrideResponse.class, () -> doCreateOverride(request));
    }

    private EmergencyOverrideResponse doCreateOverride(CreateEmergencyOverrideRequest request) {
        long startMs = toMs(request.start());
        long endMs = toMs(request.end());
        long durationMs = endMs - startMs;
        if (durationMs <= 0) {
            throw ApiException.badRequest("紧急插播结束时间必须大于开始时间");
        }
        if (durationMs > OVERRIDE_MAX_DURATION_MS) {
            throw ApiException.badRequest("紧急插播时长不得超过 30 分钟");
        }
        LocalDate startDay = request.start().atZoneSameInstant(ZONE).toLocalDate();
        LocalDate endDay = request.end().atZoneSameInstant(ZONE).toLocalDate();
        if (!startDay.equals(endDay)) {
            throw ApiException.badRequest("紧急插播起止时间必须处于同一 Asia/Shanghai 业务日");
        }

        repo.lockChannelForUpdate(request.channelId());
        var channel = repo.findChannel(request.channelId())
                .orElseThrow(() -> ApiException.notFound("频道不存在: " + request.channelId()));
        AssetRow asset = repo.findAsset(request.assetId())
                .orElseThrow(() -> ApiException.notFound("素材不存在: " + request.assetId()));
        if (channel.fallbackAssetId().equals(request.assetId())) {
            throw ApiException.unprocessable("FALLBACK_ASSET_NOT_GRANTABLE",
                    "保底素材不得用于紧急插播");
        }

        // 同键语义：已存在（含已取消）即冲突，重放创建不能复活已取消插播。
        if (repo.findOverrideForUpdate(request.overrideKey()).isPresent()) {
            throw ApiException.conflict("DUPLICATE_OVERRIDE_KEY",
                    "紧急插播 overrideKey 已存在: " + request.overrideKey());
        }

        // 锁定授权行：与撤销事务按提交顺序串行。撤销先提交时 revoked=1，此处 422 拒绝。
        GrantRow grant = repo.findGrantForUpdate(request.grantId())
                .orElseThrow(() -> ApiException.notFound("授权不存在: " + request.grantId()));
        if (!grant.channelId().equals(request.channelId()) || !grant.assetId().equals(request.assetId())) {
            throw ApiException.unprocessable("GRANT_NOT_MATCHED",
                    "指定授权不属于该频道或素材: " + request.grantId());
        }
        if (grant.revoked()) {
            throw ApiException.unprocessable("GRANT_INVALID",
                    "指定授权已撤销: " + request.grantId());
        }
        if (grant.validFromMs() > startMs || grant.validToMs() < endMs) {
            throw ApiException.unprocessable("GRANT_NOT_COVERING",
                    "指定授权未完整覆盖插播区间: " + request.grantId());
        }

        List<OverrideRow> samePriorityOverlapping = repo.findActiveOverlappingForUpdate(
                request.channelId(), request.priority(), startMs, endMs);
        if (!samePriorityOverlapping.isEmpty()) {
            throw ApiException.conflict("OVERRIDE_INTERVAL_CONFLICT",
                    "同频道同优先级 ACTIVE 插播区间重叠: "
                            + samePriorityOverlapping.get(0).overrideKey());
        }

        // 赞助商排他完整最终编排：新插播 + 同频道时段全部 ACTIVE 插播 + 最新 PUBLISHED 快照占位。
        long dayStartMs = startDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
        long dayEndMs = startDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();
        List<Item> items = new ArrayList<>();
        items.add(new Item(request.overrideKey(), request.assetId(), asset.sponsorKey(),
                startMs, endMs, true));
        for (OverrideRow existing :
                repo.findAllActiveOverlappingForUpdate(request.channelId(), startMs, endMs)) {
            items.add(new Item(existing.overrideKey(), existing.assetId(), existing.sponsorKey(),
                    existing.startMs(), existing.endMs(), false));
        }
        repo.findLatestPublication(request.channelId(), startDay).ifPresent(publication -> {
            for (PublicationSegmentRow segment : repo.findPublicationSegments(publication.id())) {
                items.add(new Item(segment.segmentId(), segment.assetId(), segment.sponsorKey(),
                        segment.startMs(), segment.endMs(), false));
            }
        });
        List<Window> windows = repo.findActiveWindowsForChannelForUpdate(
                        request.channelId(), startDay, dayStartMs, dayEndMs).stream()
                .map(PlayoutService::toWindow).toList();
        List<Conflict> conflicts = SponsorExclusivity.evaluateChannel(
                request.channelId(), items, windows);
        if (!conflicts.isEmpty()) {
            throw ApiException.sponsorConflict(toConflictDtos(conflicts));
        }

        long createdAtMs = nowMs();
        try {
            repo.insertOverride(request.overrideKey(), request.channelId(), request.assetId(),
                    asset.sponsorKey(), request.grantId(), request.priority(), startMs, endMs,
                    startDay, createdAtMs);
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("DUPLICATE_OVERRIDE_KEY",
                    "紧急插播 overrideKey 已存在: " + request.overrideKey());
        }
        return new EmergencyOverrideResponse(request.overrideKey(), request.channelId(),
                request.assetId(), asset.sponsorKey(), request.grantId(), request.priority(),
                request.start(), request.end(), OverrideStatus.ACTIVE, null, null,
                atMs(createdAtMs));
    }

    /**
     * 取消紧急插播：仅 ACTIVE 可取消，已取消再取消为 409 状态冲突；取消提交后释放同优先级
     * 冲突区间与赞助商占位。携带 requestId 幂等：同键同参返回首次结果（含 CANCELLED 明细），
     * 改参 409，失败不占键。
     */
    @Transactional
    public EmergencyOverrideResponse cancelEmergencyOverride(String overrideKey, String requestId) {
        String hash = sha256(OP_CANCEL_OVERRIDE + "|" + overrideKey);
        return idempotent(requestId, OP_CANCEL_OVERRIDE, hash, EmergencyOverrideResponse.class, () -> {
            // 先在频道锁上与同频道创建/取消串行，取消提交后并发创建即可复用该区间。
            OverrideRow existing = repo.findOverride(overrideKey)
                    .orElseThrow(() -> ApiException.notFound("紧急插播不存在: " + overrideKey));
            repo.lockChannelForUpdate(existing.channelId());
            int updated = repo.cancelOverride(overrideKey, requestId, nowMs());
            if (updated == 0) {
                throw ApiException.conflict("OVERRIDE_NOT_ACTIVE",
                        "紧急插播已取消，不能重复取消: " + overrideKey);
            }
            return toOverrideResponse(repo.findOverrideForUpdate(overrideKey).orElseThrow());
        });
    }

    /** 查询紧急插播明细（不做状态校验，ACTIVE/CANCELLED 均返回，含取消情况与原授权关联）。 */
    @Transactional(readOnly = true)
    public EmergencyOverrideResponse getEmergencyOverride(String overrideKey) {
        OverrideRow row = repo.findOverride(overrideKey)
                .orElseThrow(() -> ApiException.notFound("紧急插播不存在: " + overrideKey));
        return toOverrideResponse(row);
    }

    private static EmergencyOverrideResponse toOverrideResponse(OverrideRow row) {
        return new EmergencyOverrideResponse(row.overrideKey(), row.channelId(), row.assetId(),
                row.sponsorKey(), row.grantId(), row.priority(), atMs(row.startMs()), atMs(row.endMs()),
                row.active() ? OverrideStatus.ACTIVE : OverrideStatus.CANCELLED,
                row.cancelRequestId(),
                row.cancelledAtMs() == null ? null : atMs(row.cancelledAtMs()),
                atMs(row.createdAtMs()));
    }

    // ---------- 赞助排他窗口 ----------

    /**
     * 为赞助商在运营日登记排他窗：UTC 半开区间必须落在该运营日内且终点大于起点，频道集合不得
     * 为空且频道均存在；同一赞助商在同一频道的 ACTIVE 窗口区间不得重叠（相邻合法），违反返回
     * 422。按频道 ID 升序锁频道行后锁命中窗口行，与发布、紧急插播、其他登记按提交顺序串行。
     * 携带 requestId 幂等：同键同参返回首次结果，改参 409，失败不占键。
     */
    @Transactional
    public SponsorWindowResponse registerSponsorWindow(String sponsorKey, LocalDate businessDay,
                                                       RegisterSponsorWindowRequest request) {
        String normalizedSponsor = requireSponsorKey(sponsorKey);
        List<String> channels = normalizeChannels(request.channelIds());
        String hash = sha256(OP_REGISTER_WINDOW + "|" + normalizedSponsor + "|" + businessDay + "|"
                + toMs(request.start()) + "|" + toMs(request.end()) + "|" + String.join(",", channels));
        return idempotent(request.requestId(), OP_REGISTER_WINDOW, hash,
                SponsorWindowResponse.class,
                () -> doRegisterWindow(normalizedSponsor, businessDay, request, channels));
    }

    private SponsorWindowResponse doRegisterWindow(String sponsorKey, LocalDate businessDay,
                                                   RegisterSponsorWindowRequest request,
                                                   List<String> channels) {
        long startMs = toMs(request.start());
        long endMs = toMs(request.end());
        if (endMs <= startMs) {
            throw ApiException.unprocessable("WINDOW_INVALID_TIME",
                    "排他窗结束时间必须大于开始时间");
        }
        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();
        if (startMs < dayStartMs || endMs > dayEndMs) {
            throw ApiException.unprocessable("WINDOW_INVALID_TIME",
                    "排他窗必须完全处于运营日 " + businessDay + " 内");
        }
        for (String channelId : channels) {
            if (repo.findChannel(channelId).isEmpty()) {
                throw ApiException.notFound("频道不存在: " + channelId);
            }
        }

        // 固定顺序锁频道行，避免与发布/插播/其他登记交叉死锁。
        for (String channelId : channels) {
            repo.lockChannelForUpdate(channelId);
        }
        List<SponsorWindowRow> overlapping = repo.findOverlappingSponsorWindowsForUpdate(
                sponsorKey, startMs, endMs, channels);
        for (SponsorWindowRow window : overlapping) {
            Set<String> windowChannels = new TreeSet<>(repo.findSponsorWindowChannels(window.id()));
            for (String channelId : channels) {
                if (windowChannels.contains(channelId)) {
                    throw ApiException.unprocessable("SPONSOR_WINDOW_OVERLAP",
                            "赞助商 " + sponsorKey + " 在频道 " + channelId + " 的排他窗与窗口 "
                                    + window.id() + " 时间重叠");
                }
            }
        }

        long version = repo.nextSponsorWindowVersion(sponsorKey) + 1;
        long createdAtMs = nowMs();
        long windowId;
        try {
            windowId = repo.insertSponsorWindow(sponsorKey, businessDay, version,
                    startMs, endMs, createdAtMs);
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("SPONSOR_WINDOW_VERSION_CONFLICT",
                    "排他窗版本并发冲突，赞助商 " + sponsorKey + " 版本 " + version);
        }
        for (String channelId : channels) {
            repo.insertSponsorWindowChannel(windowId, channelId);
        }
        return toWindowResponse(repo.findSponsorWindow(windowId).orElseThrow(), channels);
    }

    /**
     * 删除（撤销）排他窗：仅 ACTIVE 可删，删除后新发布/插播不再受其限制，但已发布快照固化的
     * 命中历史不变。幂等：同 requestId 同参返回首次结果，重复删除返回 409。
     */
    @Transactional
    public SponsorWindowResponse cancelSponsorWindow(long windowId, String requestId) {
        String hash = sha256(OP_CANCEL_WINDOW + "|" + windowId);
        return idempotent(requestId, OP_CANCEL_WINDOW, hash, SponsorWindowResponse.class, () -> {
            SponsorWindowRow window = repo.findSponsorWindowForUpdate(windowId)
                    .orElseThrow(() -> ApiException.notFound("排他窗不存在: " + windowId));
            if (!window.active()) {
                throw ApiException.conflict("SPONSOR_WINDOW_ALREADY_CANCELLED",
                        "排他窗已删除: " + windowId);
            }
            int updated = repo.cancelSponsorWindow(windowId, requestId, nowMs());
            if (updated == 0) {
                throw ApiException.conflict("SPONSOR_WINDOW_ALREADY_CANCELLED",
                        "排他窗已删除: " + windowId);
            }
            SponsorWindowRow latest = repo.findSponsorWindowForUpdate(windowId).orElseThrow();
            return toWindowResponse(latest, repo.findSponsorWindowChannels(windowId));
        });
    }

    /** 查询排他窗明细（含频道范围与数量、实际时长；ACTIVE/CANCELLED 均返回）。 */
    @Transactional(readOnly = true)
    public SponsorWindowResponse getSponsorWindow(long windowId) {
        SponsorWindowRow window = repo.findSponsorWindow(windowId)
                .orElseThrow(() -> ApiException.notFound("排他窗不存在: " + windowId));
        return toWindowResponse(window, repo.findSponsorWindowChannels(windowId));
    }

    /** 查询赞助商在某运营日登记的全部窗口（含已删除），按版本升序，查询不改变状态。 */
    @Transactional(readOnly = true)
    public List<SponsorWindowResponse> listSponsorWindows(String sponsorKey, LocalDate businessDay) {
        requireSponsorKey(sponsorKey);
        List<SponsorWindowRow> windows = repo.findWindowsForSponsorDay(sponsorKey, businessDay);
        List<SponsorWindowResponse> responses = new ArrayList<>();
        for (SponsorWindowRow window : windows) {
            responses.add(toWindowResponse(window, repo.findSponsorWindowChannels(window.id())));
        }
        return responses;
    }

    /**
     * 频道运营日排他诊断：逐个 ACTIVE 窗口返回窗口时长、窗内本赞助商实际排入时长、异赞助商
     * 实际排入时长、未覆盖时长（差额）与当前生效素材的冲突明细。生效素材取最新 PUBLISHED 快照
     * 片段与 ACTIVE 紧急插播（插播时段覆盖节目）。只读。
     */
    @Transactional(readOnly = true)
    public List<SponsorWindowDiagnostic> sponsorDiagnostics(String channelId, LocalDate businessDay) {
        if (repo.findChannel(channelId).isEmpty()) {
            throw ApiException.notFound("频道不存在: " + channelId);
        }
        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();

        // 组装生效素材时段：节目片段被插播区间扣除，再加回插播时段。
        List<Item> programItems = new ArrayList<>();
        repo.findLatestPublication(channelId, businessDay).ifPresent(publication -> {
            for (PublicationSegmentRow segment : repo.findPublicationSegments(publication.id())) {
                programItems.add(new Item(segment.segmentId(), segment.assetId(),
                        segment.sponsorKey(), segment.startMs(), segment.endMs(), false));
            }
        });
        List<OverrideRow> overrides = repo.findActiveOverridesForDay(channelId, businessDay);
        List<SponsorExclusivity.Interval> overrideIntervals = overrides.stream()
                .map(o -> new SponsorExclusivity.Interval(o.startMs(), o.endMs())).toList();

        List<Window> windows = repo.findActiveWindowsForChannel(
                        channelId, businessDay, dayStartMs, dayEndMs).stream()
                .map(PlayoutService::toWindow).toList();

        // 诊断视角的冲突：窗口与当前全部生效素材（节目+插播）评估。
        List<Item> allEffective = new ArrayList<>(programItems);
        for (OverrideRow override : overrides) {
            allEffective.add(new Item(override.overrideKey(), override.assetId(),
                    override.sponsorKey(), override.startMs(), override.endMs(), false));
        }
        List<Item> freshView = allEffective.stream()
                .map(i -> new Item(i.id(), i.assetId(), i.sponsorKey(),
                        i.startMs(), i.endMs(), true)).toList();
        List<Conflict> dayConflicts = SponsorExclusivity.evaluateChannel(
                channelId, freshView, windows);

        List<SponsorWindowDiagnostic> diagnostics = new ArrayList<>();
        for (Window window : windows) {
            Map<String, List<SponsorExclusivity.Interval>> bySponsor = new LinkedHashMap<>();
            for (Item item : programItems) {
                List<SponsorExclusivity.Interval> remain = SponsorExclusivity.subtract(
                        Math.max(item.startMs(), window.startMs()),
                        Math.min(item.endMs(), window.endMs()), overrideIntervals);
                if (item.sponsorKey() != null) {
                    bySponsor.computeIfAbsent(item.sponsorKey(), k -> new ArrayList<>()).addAll(remain);
                }
            }
            for (OverrideRow override : overrides) {
                if (SponsorExclusivity.overlaps(override.startMs(), override.endMs(),
                        window.startMs(), window.endMs()) && override.sponsorKey() != null) {
                    bySponsor.computeIfAbsent(override.sponsorKey(), k -> new ArrayList<>())
                            .add(new SponsorExclusivity.Interval(
                                    Math.max(override.startMs(), window.startMs()),
                                    Math.min(override.endMs(), window.endMs())));
                }
            }
            long ownMs = 0L;
            long otherMs = 0L;
            for (Map.Entry<String, List<SponsorExclusivity.Interval>> entry : bySponsor.entrySet()) {
                long covered = SponsorExclusivity.union(entry.getValue()).stream()
                        .mapToLong(SponsorExclusivity.Interval::durationMs).sum();
                if (entry.getKey().equals(window.sponsorKey())) {
                    ownMs += covered;
                } else {
                    otherMs += covered;
                }
            }
            long windowMs = window.endMs() - window.startMs();
            long uncoveredMs = Math.max(0L, windowMs - ownMs - otherMs);
            List<SponsorConflict> conflicts = toConflictDtos(dayConflicts).stream()
                    .filter(c -> c.windowId() != null && c.windowId() == window.id())
                    .toList();
            diagnostics.add(new SponsorWindowDiagnostic(window.id(), window.version(),
                    window.sponsorKey(), atMs(window.startMs()), atMs(window.endMs()),
                    windowMs, ownMs, otherMs, uncoveredMs, conflicts));
        }
        return diagnostics;
    }

    // ---------- 内部方法 ----------

    /** 校验并规范化草稿片段：非空、区间内、不跨日、不重叠、素材存在且被单条未撤销授权完整覆盖。 */
    private List<ValidatedSegment> validateSegments(String channelId, LocalDate businessDay,
                                                    List<SegmentInput> inputs) {
        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();

        List<ValidatedSegment> segments = new ArrayList<>();
        for (SegmentInput input : inputs) {
            if (input.start() == null || input.end() == null) {
                throw ApiException.badRequest("片段开始与结束时间不能为空");
            }
            if (input.assetId() == null || input.assetId().isBlank()) {
                throw ApiException.badRequest("片段素材 ID 不能为空");
            }
            long startMs = toMs(input.start());
            long endMs = toMs(input.end());
            if (endMs <= startMs) {
                throw ApiException.badRequest("片段结束时间必须大于开始时间");
            }
            if (startMs < dayStartMs || endMs > dayEndMs) {
                throw ApiException.unprocessable("SEGMENT_CROSSES_DAY",
                        "片段不得跨业务日: " + input.start() + " ~ " + input.end());
            }
            String id = input.id() == null || input.id().isBlank()
                    ? UUID.randomUUID().toString() : input.id();
            segments.add(new ValidatedSegment(id, input.assetId(), startMs, endMs));
        }

        List<ValidatedSegment> sorted = segments.stream()
                .sorted(Comparator.comparingLong(ValidatedSegment::startMs)
                        .thenComparing(ValidatedSegment::id))
                .toList();
        for (int i = 1; i < sorted.size(); i++) {
            if (sorted.get(i).startMs() < sorted.get(i - 1).endMs()) {
                throw ApiException.unprocessable("SEGMENT_OVERLAP",
                        "片段时间重叠: " + sorted.get(i - 1).id() + " 与 " + sorted.get(i).id());
            }
        }

        for (ValidatedSegment segment : segments) {
            if (repo.findAsset(segment.assetId()).isEmpty()) {
                throw ApiException.notFound("素材不存在: " + segment.assetId());
            }
            List<GrantRow> covering = repo.findCoveringGrants(channelId, segment.assetId(),
                    segment.startMs(), segment.endMs());
            if (covering.isEmpty()) {
                throw ApiException.unprocessable("NO_COVERING_GRANT",
                        "片段未被单条有效授权完整覆盖: " + segment.id());
            }
        }
        return segments;
    }

    /** 发布时加行锁选取覆盖授权；不存在或未撤销的覆盖授权时 422 拒绝整次发布。 */
    private GrantRow selectCoveringGrantForUpdate(String channelId, SegmentRow segment) {
        List<GrantRow> candidates = repo.findCoveringGrantsForUpdate(channelId, segment.assetId(),
                segment.startMs(), segment.endMs());
        return candidates.stream()
                .filter(grant -> !grant.revoked())
                .findFirst()
                .orElseThrow(() -> ApiException.unprocessable("GRANT_INVALID",
                        "片段授权已失效，发布拒绝: " + segment.id()));
    }

    /**
     * 幂等执行：去重记录与业务结果同事务提交；同 requestId 同参数返回原结果，
     * 同 requestId 不同参数返回 409；业务失败抛异常回滚，不占用 requestId。
     */
    private <T> T idempotent(String requestId, String operation, String paramsHash,
                             Class<T> type, Supplier<T> action) {
        if (requestId == null || requestId.isBlank()) {
            throw ApiException.badRequest("requestId 不能为空");
        }
        Optional<RequestRow> existing = repo.findRequestForUpdate(requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), operation, paramsHash, type);
        }
        try {
            repo.insertRequest(requestId, operation, paramsHash, nowMs());
        } catch (DuplicateKeyException e) {
            // 并发同 requestId：等待对方事务结束后读取已提交记录
            RequestRow committed = repo.findRequestForUpdate(requestId)
                    .orElseThrow(() -> ApiException.conflict("REQUEST_ID_CONFLICT",
                            "requestId 并发冲突: " + requestId));
            return replay(committed, operation, paramsHash, type);
        }
        T result = action.get();
        try {
            repo.completeRequest(requestId, objectMapper.writeValueAsString(result));
        } catch (Exception e) {
            throw new IllegalStateException("幂等结果序列化失败", e);
        }
        return result;
    }

    private <T> T replay(RequestRow row, String operation, String paramsHash, Class<T> type) {
        if (!row.operation().equals(operation) || !row.paramsHash().equals(paramsHash)) {
            throw ApiException.conflict("REQUEST_ID_CONFLICT",
                    "requestId 已使用且参数不一致: " + row.requestId());
        }
        if (row.responseBody() == null) {
            throw ApiException.conflict("REQUEST_ID_CONFLICT",
                    "requestId 请求尚未完成: " + row.requestId());
        }
        try {
            return objectMapper.readValue(row.responseBody(), type);
        } catch (Exception e) {
            throw new IllegalStateException("幂等结果反序列化失败", e);
        }
    }

    private static String canonicalSegments(List<SegmentInput> segments) {
        StringBuilder sb = new StringBuilder();
        for (SegmentInput s : segments) {
            sb.append(s.id() == null ? "" : s.id()).append(',')
                    .append(s.assetId()).append(',')
                    .append(s.start() == null ? "" : toMs(s.start())).append(',')
                    .append(s.end() == null ? "" : toMs(s.end())).append(';');
        }
        return sb.toString();
    }

    private static String canonicalChannelInputs(List<PublishChannelInput> inputs) {
        return inputs.stream()
                .sorted(Comparator.comparing(PublishChannelInput::channelId))
                .map(i -> i.channelId() + "," + i.draftVersion() + "," + i.expectedPublishedVersion())
                .reduce("", (a, b) -> a + b + ";");
    }

    private PlayoutDecisionResponse fallback(String channelId, OffsetDateTime at, String assetId,
                                             FallbackReason reason) {
        return new PlayoutDecisionResponse(channelId, at, assetId,
                DecisionSource.FALLBACK, reason, null, null, null);
    }

    private static String normalizeSponsorKey(String sponsorKey) {
        return sponsorKey == null || sponsorKey.isBlank() ? null : sponsorKey.trim();
    }

    private static String requireSponsorKey(String sponsorKey) {
        String normalized = normalizeSponsorKey(sponsorKey);
        if (normalized == null) {
            throw ApiException.badRequest("sponsorKey 不能为空");
        }
        return normalized;
    }

    /** 规范化窗口频道集合：去空白、去重并排序；空集合（含 null）返回空列表，由调用方报 422。 */
    private static List<String> normalizeChannels(List<String> channelIds) {
        if (channelIds == null) {
            return List.of();
        }
        Set<String> distinct = new LinkedHashSet<>();
        for (String channelId : channelIds) {
            if (channelId != null && !channelId.isBlank()) {
                distinct.add(channelId.trim());
            }
        }
        if (distinct.isEmpty()) {
            throw ApiException.unprocessable("WINDOW_CHANNELS_EMPTY",
                    "排他窗频道集合不得为空");
        }
        return distinct.stream().sorted().toList();
    }

    private static Window toWindow(SponsorWindowRow row) {
        return new Window(row.id(), row.sponsorKey(), row.version(), row.startMs(), row.endMs());
    }

    private static List<SponsorConflict> toConflictDtos(List<Conflict> conflicts) {
        return conflicts.stream()
                .map(c -> new SponsorConflict(c.channelId(), atMs(c.startMs()), atMs(c.endMs()),
                        c.durationMs(), c.conflictType(), c.windowSponsorKey(),
                        c.windowId(), c.windowVersion(), c.segmentId(), c.assetId(),
                        c.assetSponsorKey(), c.conflictAssetId(), c.conflictSponsorKey()))
                .toList();
    }

    private static SponsorWindowResponse toWindowResponse(SponsorWindowRow window,
                                                          List<String> channels) {
        return new SponsorWindowResponse(window.id(), window.sponsorKey(),
                window.businessDay().toString(), window.version(),
                atMs(window.startMs()), atMs(window.endMs()),
                window.endMs() - window.startMs(), channels, channels.size(),
                window.status(), window.cancelRequestId(),
                window.cancelledAtMs() == null ? null : atMs(window.cancelledAtMs()),
                atMs(window.createdAtMs()));
    }

    private PublicationDetailResponse toPublicationDetail(PublicationRow publication,
                                                          List<PublicationSegmentRow> segments,
                                                          List<SponsorHitRow> hits) {
        List<PublicationSegmentResponse> segmentResponses = segments.stream()
                .map(s -> new PublicationSegmentResponse(s.segmentId(), s.assetId(),
                        s.sponsorKey(), s.grantId(), atMs(s.startMs()), atMs(s.endMs()),
                        s.endMs() - s.startMs()))
                .toList();
        List<SponsorHitResponse> hitResponses = hits.stream()
                .map(h -> new SponsorHitResponse(h.segmentId(), h.assetId(), h.sponsorKey(),
                        h.windowId(), h.windowVersion(), atMs(h.startMs()), atMs(h.endMs())))
                .toList();
        long scheduledDurationMs = segments.stream()
                .mapToLong(s -> s.endMs() - s.startMs()).sum();
        return new PublicationDetailResponse(publication.id(), publication.channelId(),
                publication.businessDay().toString(), publication.publishedVersion(),
                publication.draftVersion(),
                publication.published() ? PublicationStatus.PUBLISHED : PublicationStatus.CANCELLED,
                publication.cancelRequestId(),
                publication.cancelledAtMs() == null ? null : atMs(publication.cancelledAtMs()),
                atMs(publication.createdAtMs()),
                segments.size(), scheduledDurationMs, segmentResponses, hitResponses);
    }

    private static long toMs(OffsetDateTime time) {
        return time.toInstant().toEpochMilli();
    }

    private static OffsetDateTime atMs(long epochMs) {
        return OffsetDateTime.ofInstant(Instant.ofEpochMilli(epochMs), ZONE);
    }

    private long nowMs() {
        return clock.millis();
    }

    private static String sha256(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(text.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
                sb.append(Character.forDigit(b & 0xF, 16));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** 发布前的单频道计划。 */
    private record ChannelPublishPlan(String channelId, long draftVersion, long newPublishedVersion,
                                      List<SegmentRow> segments, List<Long> grantIds,
                                      List<Window> windows, List<Conflict> conflicts,
                                      long scheduledDurationMs) {
    }

    /** 校验后的片段。 */
    private record ValidatedSegment(String id, String assetId, long startMs, long endMs) {
        SegmentResponse toResponse() {
            return new SegmentResponse(id, assetId, atMs(startMs), atMs(endMs));
        }
    }
}

