package com.example.starter.playout.api;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;

import java.time.OffsetDateTime;
import java.util.List;

/**
 * 播出编排 API 的请求与响应类型。时间字段统一为 Asia/Shanghai、毫秒精度 ISO 8601。
 */
public final class Dtos {

    private Dtos() {
    }

    /** 创建素材请求；id 为空时由系统生成稳定 ID；sponsorKey 为空表示无赞助商素材。 */
    public record CreateAssetRequest(
            String id,
            @NotNull @Positive Long durationMs,
            String sponsorKey) {
    }

    /** 素材响应；sponsorKey 为 null 表示无赞助商素材。 */
    public record AssetResponse(String id, long durationMs, String sponsorKey) {
    }

    /** 创建频道请求；fallbackAssetId 为不会被撤销的保底素材。 */
    public record CreateChannelRequest(
            String id,
            @NotBlank String fallbackAssetId) {
    }

    /** 频道响应。 */
    public record ChannelResponse(String id, String fallbackAssetId) {
    }

    /** 创建授权请求，有效区间 [validFrom, validTo) 左闭右开。 */
    public record CreateGrantRequest(
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo) {
    }

    /** 授权响应。 */
    public record GrantResponse(
            long id,
            String channelId,
            String assetId,
            OffsetDateTime validFrom,
            OffsetDateTime validTo,
            boolean revoked) {
    }

    /** 撤销授权请求。 */
    public record RevokeGrantRequest(@NotBlank String requestId) {
    }

    /** 草稿片段输入；id 为空时由系统生成。 */
    public record SegmentInput(
            String id,
            @NotBlank String assetId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 整份替换草稿请求。 */
    public record ReplaceDraftRequest(
            @NotBlank String requestId,
            @NotNull @PositiveOrZero Long expectedDraftVersion,
            @NotNull List<@NotNull SegmentInput> segments) {
    }

    /** 草稿片段响应。 */
    public record SegmentResponse(
            String id,
            String assetId,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 草稿响应。 */
    public record DraftResponse(
            String channelId,
            String businessDay,
            long version,
            List<SegmentResponse> segments) {
    }

    /** 发布请求。 */
    public record PublishRequest(
            @NotBlank String requestId,
            @NotNull @Positive Long draftVersion,
            @NotNull @PositiveOrZero Long expectedPublishedVersion) {
    }

    /** 发布响应。 */
    public record PublishResponse(
            long publicationId,
            String channelId,
            String businessDay,
            long publishedVersion,
            long draftVersion) {
    }

    /** 播出决定来源：EMERGENCY 命中紧急插播，PROGRAM 命中节目片段，FALLBACK 返回保底素材。 */
    public enum DecisionSource {
        EMERGENCY, PROGRAM, FALLBACK
    }

    /** 保底原因：无已发布编排 / 处于空档 / 覆盖片段的授权已撤销。 */
    public enum FallbackReason {
        NO_PUBLISHED_SCHEDULE, GAP, GRANT_REVOKED
    }

    /** 播出决定响应；source 为 FALLBACK 时 reason 非空；source 为 EMERGENCY 时 overrideKey 非空。 */
    public record PlayoutDecisionResponse(
            String channelId,
            OffsetDateTime at,
            String assetId,
            DecisionSource source,
            FallbackReason reason,
            Long publicationId,
            String segmentId,
            String overrideKey) {
    }

    /** 紧急插播状态：创建即 ACTIVE，取消后为 CANCELLED，均为终态语义（ACTIVE 只能转为 CANCELLED）。 */
    public enum OverrideStatus {
        ACTIVE, CANCELLED
    }

    /**
     * 创建限时紧急插播请求。区间 [start, end) 左闭右开、同处一个 Asia/Shanghai 业务日、
     * 时长大于 0 且不超过 30 分钟；priority 取值 1～9；grantId 必须属于该频道与素材并完整覆盖区间。
     */
    public record CreateEmergencyOverrideRequest(
            @NotBlank String requestId,
            @NotBlank String overrideKey,
            @NotBlank String channelId,
            @NotBlank String assetId,
            @NotNull @Positive Long grantId,
            @NotNull @Min(1) @Max(9) Integer priority,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end) {
    }

    /** 取消紧急插播请求（幂等）。 */
    public record CancelEmergencyOverrideRequest(@NotBlank String requestId) {
    }

    /** 紧急插播明细响应，保存取消情况与原授权关联，不随授权撤销自动换绑。 */
    public record EmergencyOverrideResponse(
            String overrideKey,
            String channelId,
            String assetId,
            String sponsorKey,
            long grantId,
            int priority,
            OffsetDateTime start,
            OffsetDateTime end,
            OverrideStatus status,
            String cancelRequestId,
            OffsetDateTime cancelledAt,
            OffsetDateTime createdAt) {
    }

    // ---------- 赞助排他窗口 ----------

    /**
     * 登记赞助排他窗口请求。区间 [start, end) 为 UTC 左闭右开；channelIds 为命中的频道集合，不得为空；
     * 同一赞助商在同一频道的 ACTIVE 窗口区间不得重叠。
     */
    public record RegisterSponsorWindowRequest(
            @NotBlank String requestId,
            @NotNull OffsetDateTime start,
            @NotNull OffsetDateTime end,
            @NotNull @NotEmpty List<@NotBlank String> channelIds) {
    }

    /** 取消（删除）赞助窗口请求；删除不影响已发布快照固化的命中历史。 */
    public record CancelSponsorWindowRequest(@NotBlank String requestId) {
    }

    /** 赞助排他窗口明细；durationMs 为窗口实际时长（end-start），channelCount 为频道范围实际数量。 */
    public record SponsorWindowResponse(
            long id,
            String sponsorKey,
            String businessDay,
            long version,
            OffsetDateTime start,
            OffsetDateTime end,
            long durationMs,
            List<String> channelIds,
            int channelCount,
            String status,
            String cancelRequestId,
            OffsetDateTime cancelledAt,
            OffsetDateTime createdAt) {
    }

    /** 快照片段中固化的赞助窗口命中；窗口删除或修订后本记录不变。 */
    public record SponsorHitResponse(
            String segmentId,
            String assetId,
            String sponsorKey,
            long windowId,
            long windowVersion,
            OffsetDateTime start,
            OffsetDateTime end) {
    }

    /** 发布快照片段明细；sponsorKey 为发布时素材的赞助商键，null 表示无赞助商素材。 */
    public record PublicationSegmentResponse(
            String segmentId,
            String assetId,
            String sponsorKey,
            long grantId,
            OffsetDateTime start,
            OffsetDateTime end,
            long durationMs) {
    }

    /** 发布快照状态：PUBLISHED 生效中，CANCELLED 播出开始前已撤销（释放占位、保留命中历史）。 */
    public enum PublicationStatus {
        PUBLISHED, CANCELLED
    }

    /** 发布快照明细，含片段、窗口命中与撤销情况；查询不改变状态。 */
    public record PublicationDetailResponse(
            long publicationId,
            String channelId,
            String businessDay,
            long publishedVersion,
            long draftVersion,
            PublicationStatus status,
            String cancelRequestId,
            OffsetDateTime cancelledAt,
            OffsetDateTime createdAt,
            long segmentCount,
            long scheduledDurationMs,
            List<PublicationSegmentResponse> segments,
            List<SponsorHitResponse> sponsorHits) {
    }

    /** 撤销发布请求；仅尚未开始的发布可撤销。 */
    public record CancelPublicationRequest(@NotBlank String requestId) {
    }

    /** 多频道批量发布中的单频道发布目标。 */
    public record PublishChannelInput(
            @NotBlank String channelId,
            @NotNull @Positive Long draftVersion,
            @NotNull @PositiveOrZero Long expectedPublishedVersion) {
    }

    /**
     * 一次发布跨多频道请求：所有频道在完整最终编排上统一校验（授权、既有占位、排他窗），
     * 任一频道冲突则整次 409 且不留下部分频道更新。
     */
    public record PublishBatchRequest(
            @NotBlank String requestId,
            @NotNull @NotEmpty List<@NotNull @Valid PublishChannelInput> channels) {
    }

    /** 单频道发布结果；scheduledDurationMs 为该频道最终编排实际播出总时长。 */
    public record PublishChannelResult(
            String channelId,
            long publicationId,
            long publishedVersion,
            long draftVersion,
            long segmentCount,
            long scheduledDurationMs) {
    }

    /** 多频道批量发布结果；数量返回要求值（requestedChannelCount）与实际值（publishedChannelCount）。 */
    public record PublishBatchResponse(
            String businessDay,
            int requestedChannelCount,
            int publishedChannelCount,
            long scheduledDurationMs,
            List<PublishChannelResult> channels) {
    }

    /** 单条赞助商排他冲突明细：频道、命中时段、窗口与冲突素材。 */
    public record SponsorConflict(
            String channelId,
            OffsetDateTime start,
            OffsetDateTime end,
            long durationMs,
            String conflictType,
            String windowSponsorKey,
            Long windowId,
            Long windowVersion,
            String segmentId,
            String assetId,
            String assetSponsorKey,
            String conflictAssetId,
            String conflictSponsorKey) {
    }

    /** 409 冲突响应的结构化明细。 */
    public record SponsorConflictDetail(List<SponsorConflict> conflicts) {
    }

    /** 排他诊断行：某频道某业务日命中的 ACTIVE 窗口及该窗口内各赞助商实际排入时长。 */
    public record SponsorWindowDiagnostic(
            long windowId,
            long windowVersion,
            String sponsorKey,
            OffsetDateTime start,
            OffsetDateTime end,
            long windowDurationMs,
            long ownScheduledDurationMs,
            long otherScheduledDurationMs,
            long uncoveredDurationMs,
            List<SponsorConflict> conflicts) {
    }

    /** 统一错误响应体。 */
    public record ErrorResponse(String error, String message) {
    }
}

