package com.example.starter.playout;

import com.example.starter.playout.SponsorExclusivity.Conflict;
import com.example.starter.playout.SponsorExclusivity.Interval;
import com.example.starter.playout.SponsorExclusivity.Item;
import com.example.starter.playout.SponsorExclusivity.Window;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 赞助商排他冲突检测纯单元测试：覆盖窗口命中、异赞助商相交、同赞助商并存、左闭右开边界、
 * 历史项不互相裁决、区间并集与扣除等边界。
 */
class SponsorExclusivityTest {

    private static Item item(String id, String sponsor, long start, long end, boolean fresh) {
        return new Item(id, "asset-" + id, sponsor, start, end, fresh);
    }

    private static Window window(long id, String sponsor, long start, long end) {
        return new Window(id, sponsor, 7L, start, end);
    }

    @Test
    void adjacentHalfOpenIntervalsDoNotOverlap() {
        assertThat(SponsorExclusivity.overlaps(0, 10, 10, 20)).isFalse();
        assertThat(SponsorExclusivity.overlaps(10, 20, 0, 10)).isFalse();
        assertThat(SponsorExclusivity.overlaps(0, 10, 9, 20)).isTrue();
    }

    @Test
    void sameSponsorDifferentAssetsCanCoexistInsideWindow() {
        List<Item> items = List.of(
                item("a", "NIKE", 0, 10, true),
                item("b", "NIKE", 5, 15, true));
        Window window = window(1, "NIKE", 0, 20);

        assertThat(SponsorExclusivity.evaluateChannel("ch", items, List.of(window))).isEmpty();
    }

    @Test
    void differentSponsorItemsOverlappingConflictWithIntersection() {
        List<Item> items = List.of(
                item("a", "NIKE", 0, 10, true),
                item("b", "ADIDAS", 6, 16, true));

        List<Conflict> conflicts =
                SponsorExclusivity.evaluateChannel("ch", items, List.of());

        assertThat(conflicts).hasSize(1);
        Conflict conflict = conflicts.get(0);
        assertThat(conflict.channelId()).isEqualTo("ch");
        assertThat(conflict.conflictType()).isEqualTo("SPONSOR_OVERLAP");
        assertThat(conflict.startMs()).isEqualTo(6);
        assertThat(conflict.endMs()).isEqualTo(10);
        assertThat(conflict.durationMs()).isEqualTo(4);
        assertThat(conflict.assetSponsorKey()).isEqualTo("NIKE");
        assertThat(conflict.conflictSponsorKey()).isEqualTo("ADIDAS");
    }

    @Test
    void nullSponsorItemsNeverConflictWithEachOtherOrSponsored() {
        List<Item> items = List.of(
                item("a", null, 0, 10, true),
                item("b", null, 3, 13, true),
                item("c", "NIKE", 5, 8, true));

        assertThat(SponsorExclusivity.evaluateChannel("ch", items, List.of())).isEmpty();
    }

    @Test
    void windowViolationForDifferentAndNullSponsorWithIntersection() {
        Window nikeWindow = window(1, "NIKE", 10, 20);
        List<Item> items = List.of(
                item("a", "ADIDAS", 0, 15, true),
                item("b", null, 18, 25, true));

        List<Conflict> conflicts =
                SponsorExclusivity.evaluateChannel("ch", items, List.of(nikeWindow));

        assertThat(conflicts).hasSize(2);
        assertThat(conflicts).extracting(Conflict::conflictType)
                .containsOnly("WINDOW_VIOLATION");
        assertThat(conflicts).extracting(Conflict::startMs).containsExactly(10L, 18L);
        assertThat(conflicts).extracting(Conflict::endMs).containsExactly(15L, 20L);
        assertThat(conflicts).extracting(Conflict::windowId).containsOnly(1L);
        assertThat(conflicts).extracting(Conflict::windowVersion).containsOnly(7L);
    }

    @Test
    void windowBoundaryIsHalfOpenAdjacentSegmentsAllowed() {
        Window window = window(1, "NIKE", 10, 20);
        // 终点等于窗口起点、起点等于窗口终点：均不命中窗口
        List<Item> items = List.of(
                item("before", "ADIDAS", 0, 10, true),
                item("after", "ADIDAS", 20, 30, true));

        assertThat(SponsorExclusivity.evaluateChannel("ch", items, List.of(window))).isEmpty();
    }

    @Test
    void existingItemsDoNotConflictBetweenEachOtherButFreshVsExistingDoes() {
        // 两条历史异赞助商素材相交，不报冲突；新片段与其中一条冲突须报。
        List<Item> items = List.of(
                item("old-a", "NIKE", 0, 20, false),
                item("old-b", "ADIDAS", 5, 25, false),
                item("new", "PUMA", 22, 30, true));

        List<Conflict> conflicts =
                SponsorExclusivity.evaluateChannel("ch", items, List.of());

        assertThat(conflicts).hasSize(1);
        assertThat(conflicts.get(0).segmentId()).isEqualTo("new");
        assertThat(conflicts.get(0).assetSponsorKey()).isEqualTo("PUMA");
        assertThat(conflicts.get(0).conflictSponsorKey()).isEqualTo("ADIDAS");
    }

    @Test
    void conflictOrderingIsStable() {
        Window window = window(1, "NIKE", 0, 100);
        List<Item> items = List.of(
                item("later", "ADIDAS", 50, 60, true),
                item("earlier", "ADIDAS", 10, 20, true));

        List<Conflict> conflicts =
                SponsorExclusivity.evaluateChannel("ch", items, List.of(window));

        assertThat(conflicts).extracting(Conflict::startMs).containsExactly(10L, 50L);
    }

    @Test
    void unionMergesOverlappingAndAdjacentIntervals() {
        List<Interval> merged = SponsorExclusivity.union(List.of(
                new Interval(10, 20), new Interval(15, 30), new Interval(30, 40),
                new Interval(50, 60), new Interval(0, 0)));

        assertThat(merged).containsExactly(new Interval(10, 40), new Interval(50, 60));
        assertThat(merged).extracting(Interval::durationMs).containsExactly(30L, 10L);
    }

    @Test
    void subtractRemovesBlockerUnionFromHalfOpenRange() {
        List<Interval> remain = SponsorExclusivity.subtract(0, 100, List.of(
                new Interval(10, 20), new Interval(15, 30), new Interval(80, 120)));

        assertThat(remain).containsExactly(new Interval(0, 10), new Interval(30, 80));
        assertThat(remain.stream().mapToLong(Interval::durationMs).sum()).isEqualTo(60L);
    }

    @Test
    void subtractFullCoverageLeavesNothing() {
        assertThat(SponsorExclusivity.subtract(0, 10, List.of(new Interval(0, 10)))).isEmpty();
        assertThat(SponsorExclusivity.subtract(0, 10, List.of(new Interval(-5, 15)))).isEmpty();
    }
}

