    @Test
    void publishEnforcesWindowAndFreezesHitVersion() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        long nikeGrant = createGrant(ch, p + "nike", "NIKE");
        long adidasGrant = createGrant(ch, p + "adidas", "ADIDAS");
        assertThat(nikeGrant).isNotEqualTo(adidasGrant);

        // NIKE 窗口 10:00-11:00
        long windowId = registerWindowOk("NIKE", "req-" + p + "-w", ch, T_10, T_11);

        // 异赞助商片段在窗内 → 409，返回频道、相交时段与冲突素材
        putDraft(ch, "req-" + p + "-d1", 0,
                segment(p + "s1", p + "adidas", T_1020, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish", publishBody("req-" + p + "-p1", 1, 0))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].channelId").value(ch))
                .andExpect(jsonPath("$.details.conflicts[0].start").value(T_1020))
                .andExpect(jsonPath("$.details.conflicts[0].end").value(T_1040))
                .andExpect(jsonPath("$.details.conflicts[0].durationMs").value(1200000))
                .andExpect(jsonPath("$.details.conflicts[0].windowId").value(windowId))
                .andExpect(jsonPath("$.details.conflicts[0].windowSponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.details.conflicts[0].assetId").value(p + "adidas"))
                .andExpect(jsonPath("$.details.conflicts[0].assetSponsorKey").value("ADIDAS"));

        // 失败不留发布：播出仍无已发布编排
        playout(ch, T_1030).andExpect(jsonPath("$.source").value("FALLBACK"));

        // 同赞助商片段在窗内 + 窗外异赞助商片段并存 → 成功
        putDraft(ch, "req-" + p + "-d2", 1,
                segment(p + "s2", p + "adidas", T_09, T_0930),
                segment(p + "s3", p + "nike", T_1020, T_1040));
        MvcResult published = postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p2", 2, 0))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(1))
                .andReturn();
        long publicationId = readJson(published).get("publicationId").asLong();

        // 快照明细：固化 sponsorKey 与命中窗口版本
        getJson("/api/publications/" + publicationId)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PUBLISHED"))
                .andExpect(jsonPath("$.segmentCount").value(2))
                .andExpect(jsonPath("$.scheduledDurationMs").value(3000000))
                .andExpect(jsonPath("$.segments[1].sponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.segments[0].sponsorKey").value("ADIDAS"))
                .andExpect(jsonPath("$.sponsorHits[0].segmentId").value(p + "s3"))
                .andExpect(jsonPath("$.sponsorHits[0].sponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.sponsorHits[0].windowId").value(windowId))
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1));

        // 删除窗口后再修订版本（再登记为版本 2），历史快照命中仍固化版本 1
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + p + "-wc")).andExpect(status().isOk());
        registerWindowOk("NIKE", "req-" + p + "-w2", ch, T_10, T_11);
        getJson("/api/publications/" + publicationId)
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1))
                .andExpect(jsonPath("$.sponsorHits[0].windowId").value(windowId));

        // 窗口删除后，异赞助商新发布不再受限
        putDraft(ch, "req-" + p + "-d3", 2,
                segment(p + "s4", p + "adidas", T_1020, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p3", 3, 1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(2));
    }

