                .andExpect(jsonPath("$.details.conflicts[0].conflictAssetId").value(p + "adidas"));
        // 相邻不冲突
        createOverride(p + "ov-y", ch2, p + "nike", nikeGrantCh2, 5, T_11,
                "2026-09-22T11:20:00.000+08:00", "req-" + p + "-o6")
