package com.example.starter.playout;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.ResultActions;

import java.time.Clock;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 播出赞助排他 H2（MODE=MySQL）真实数据库端到端测试：窗口登记、草稿发布（单/多频道）、
 * 紧急插播排他校验、快照固化、发布撤销、诊断查询、幂等与并发提交顺序裁决。
 */
@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
class SponsorExclusivityApiTest {

    private static final String DAY = "2026-09-22";
    private static final String GRANT_FROM = "2026-09-22T00:00:00.000+08:00";
    private static final String GRANT_TO = "2026-09-23T00:00:00.000+08:00";
    private static final String T_09 = "2026-09-22T09:00:00.000+08:00";
    private static final String T_0930 = "2026-09-22T09:30:00.000+08:00";
    private static final String T_10 = "2026-09-22T10:00:00.000+08:00";
    private static final String T_1020 = "2026-09-22T10:20:00.000+08:00";
    private static final String T_1030 = "2026-09-22T10:30:00.000+08:00";
    private static final String T_1040 = "2026-09-22T10:40:00.000+08:00";
    private static final String T_11 = "2026-09-22T11:00:00.000+08:00";

    @Autowired
    private MockMvc mvc;

    @Autowired
    private ObjectMapper objectMapper;

    /** 可控时钟：撤销发布的“尚未开始”判定依赖当前时间。 */
    @MockitoBean
    private Clock clock;

    // ---------- 素材 sponsorKey 透传 ----------

    @Test
    void assetCarriesSponsorKeyAndNullMeansNoSponsor() throws Exception {
        String p = prefix();
        postJson("/api/assets", Map.of("id", p + "a", "durationMs", 1000, "sponsorKey", "NIKE"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value("NIKE"));
        postJson("/api/assets", Map.of("id", p + "b", "durationMs", 1000))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").isEmpty());
    }

    // ---------- 窗口登记主流程与 422 分支 ----------

    @Test
    void registerWindowSuccessCountsDurationAndOverlapRules() throws Exception {
        String p = prefix();
        String ch1 = newChannel(p, "1");
        String ch2 = newChannel(p, "2");

        // 主流程：版本 1，返回实际时长与频道数量
        MvcResult result = registerWindow("NIKE", "req-" + p + "-w1",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch2, ch1)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.businessDay").value(DAY))
                .andExpect(jsonPath("$.version").value(1))
                .andExpect(jsonPath("$.durationMs").value(3600000))
                .andExpect(jsonPath("$.channelCount").value(2))
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andReturn();
        long windowId = readJson(result).get("id").asLong();

        // 明细：频道排序确定、时间毫秒精度
        getJson("/api/sponsor-windows/" + windowId)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.channelIds[0]").value(ch1))
                .andExpect(jsonPath("$.channelIds[1]").value(ch2))
                .andExpect(jsonPath("$.start").value(T_10))
                .andExpect(jsonPath("$.end").value(T_11));

        // 同赞助商同频道窗口重叠 → 422（另一频道不重叠也不行）
        registerWindow("NIKE", "req-" + p + "-w2",
                Map.of("start", T_1030, "end", "2026-09-22T11:30:00.000+08:00",
                        "channelIds", List.of(ch2))))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("SPONSOR_WINDOW_OVERLAP"));

        // 相邻（左闭右开）合法
        registerWindow("NIKE", "req-" + p + "-w3",
                Map.of("start", T_11, "end", "2026-09-22T12:00:00.000+08:00",
                        "channelIds", List.of(ch1))))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));

        // 不同赞助商同频道同时段允许并存
        registerWindow("ADIDAS", "req-" + p + "-w4",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch1))))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1));

        // 422：频道集合为空
        registerWindow("NIKE", "req-" + p + "-empty",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of()))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("WINDOW_CHANNELS_EMPTY"));

        // 422：时间非法（终点 <= 起点）
        registerWindow("NIKE", "req-" + p + "-bad1",
                Map.of("start", T_11, "end", T_10, "channelIds", List.of(ch1)))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("WINDOW_INVALID_TIME"));

        // 422：跨运营日
        registerWindow("NIKE", "req-" + p + "-bad2",
                Map.of("start", "2026-09-22T23:30:00.000+08:00",
                        "end", "2026-09-23T00:30:00.000+08:00",
                        "channelIds", List.of(ch1)))
                .andExpect(status().isUnprocessableEntity());

        // 404：频道不存在
        registerWindow("NIKE", "req-" + p + "-bad3",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(p + "ghost")))
                .andExpect(status().isNotFound());
    }

    // ---------- 窗口登记幂等：重放、异参 409、失败不占键 ----------

    @Test
    void windowRegistrationIdempotency() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        Map<String, Object> body = Map.of("start", T_10, "end", T_11,
                "channelIds", List.of(ch));

        MvcResult first = registerWindow("NIKE", "req-" + p + "-idem", body)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1))
                .andReturn();
        long firstId = readJson(first).get("id").asLong();

        // 同参重放：返回首次结果，不产生新版本
        MvcResult replay = registerWindow("NIKE", "req-" + p + "-idem", body)
                .andExpect(status().isOk()).andReturn();
        assertThat(readJson(replay).get("id").asLong()).isEqualTo(firstId);

        // 异参 409
        registerWindow("NIKE", "req-" + p + "-idem",
                Map.of("start", T_1020, "end", T_11, "channelIds", List.of(ch)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));

        // 失败不占键：先用空频道集合失败，再用同 requestId 成功
        registerWindow("NIKE", "req-" + p + "-retry",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of()))
                .andExpect(status().isUnprocessableEntity());
        registerWindow("NIKE", "req-" + p + "-retry",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));
    }

    // ---------- 窗口删除与列表 ----------

    @Test
    void cancelWindowKeepsHistoryAndIsIdempotent() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        long windowId = registerWindowOk("NIKE", "req-" + p + "-w", ch, T_10, T_11);

        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"))
                .andExpect(jsonPath("$.cancelRequestId").value("req-" + p + "-c"))
                .andExpect(jsonPath("$.cancelledAt").isNotEmpty());
        // 重放
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));
        // 新请求重复删除 → 409
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + p + "-c2"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_WINDOW_ALREADY_CANCELLED"));
        // 404
        postJson("/api/sponsor-windows/999999/cancel", Map.of("requestId", "req-" + p + "-x"))
                .andExpect(status().isNotFound());

        // 列表含已删除窗口，按版本排序
        getJson("/api/sponsors/NIKE/windows/" + DAY)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].id").value(windowId))
                .andExpect(jsonPath("$[0].status").value("CANCELLED"));
    }

    // ---------- 发布排他主流程、409 明细与快照固化 ----------

    @Test
    void publishEnforcesWindowAndFreezesHitVersion() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        long nikeGrant = createGrant(ch, p + "nike", "NIKE");
        long adidasGrant = createGrant(ch, p + "adidas", "ADIDAS");
        assertThat(nikeGrant).isNotEqualTo(adidasGrant);

        // NIKE 窗口 10:00-11:00
        long windowId = registerWindowOk("NIKE", "req-" + p + "-w", ch, T_10, T_11);

        // 异赞助商片段在窗内 → 409，返回频道、相交时段与冲突素材
        putDraft(ch, "req-" + p + "-d1", 0,
                segment(p + "s1", p + "adidas", T_1020, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish", publishBody("req-" + p + "-p1", 1, 0))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].channelId").value(ch))
                .andExpect(jsonPath("$.details.conflicts[0].start").value(T_1020))
                .andExpect(jsonPath("$.details.conflicts[0].end").value(T_1040))
                .andExpect(jsonPath("$.details.conflicts[0].durationMs").value(1200000))
                .andExpect(jsonPath("$.details.conflicts[0].windowId").value(windowId))
                .andExpect(jsonPath("$.details.conflicts[0].windowSponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.details.conflicts[0].assetId").value(p + "adidas"))
                .andExpect(jsonPath("$.details.conflicts[0].assetSponsorKey").value("ADIDAS"));

        // 失败不留发布：播出仍无已发布编排
        playout(ch, T_1030).andExpect(jsonPath("$.source").value("FALLBACK"));

        // 同赞助商片段在窗内 + 窗外异赞助商片段并存 → 成功
        putDraft(ch, "req-" + p + "-d2", 1,
                segment(p + "s2", p + "adidas", T_09, T_0930),
                segment(p + "s3", p + "nike", T_1020, T_1040));
        MvcResult published = postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p2", 2, 0))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(1))
                .andReturn();
        long publicationId = readJson(published).get("publicationId").asLong();

        // 快照明细：固化 sponsorKey 与命中窗口版本
        getJson("/api/publications/" + publicationId)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PUBLISHED"))
                .andExpect(jsonPath("$.segmentCount").value(2))
                .andExpect(jsonPath("$.scheduledDurationMs").value(3000000))
                .andExpect(jsonPath("$.segments[1].sponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.segments[0].sponsorKey").value("ADIDAS"))
                .andExpect(jsonPath("$.sponsorHits[0].segmentId").value(p + "s3"))
                .andExpect(jsonPath("$.sponsorHits[0].sponsorKey").value("NIKE"))
                .andExpect(jsonPath("$.sponsorHits[0].windowId").value(windowId))
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1));

        // 删除窗口后再修订版本（再登记为版本 2），历史快照命中仍固化版本 1
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + p + "-wc")).andExpect(status().isOk());
        registerWindowOk("NIKE", "req-" + p + "-w2", ch, T_10, T_11);
        getJson("/api/publications/" + publicationId)
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1))
                .andExpect(jsonPath("$.sponsorHits[0].windowId").value(windowId));

        // 窗口删除后，异赞助商新发布不再受限
        putDraft(ch, "req-" + p + "-d3", 2,
                segment(p + "s4", p + "adidas", T_1020, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p3", 3, 1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(2));
    }

    @Test
    void publishRejectsUnsponsoredAssetInsideWindowAndAdjacentIsAllowed() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        // 无赞助商素材需要授权（保底素材不可授权，这里新建普通无赞助商素材）
        postJson("/api/assets", Map.of("id", p + "neutral", "durationMs", 3600000))
                .andExpect(status().isOk());
        createGrant(ch, p + "neutral", null);
        registerWindowOk("NIKE", "req-" + p + "-w", ch, T_10, T_11);

        // 与窗口相邻（09:00-10:00）合法
        putDraft(ch, "req-" + p + "-d1", 0,
                segment(p + "s1", p + "neutral", T_09, T_10));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p1", 1, 0))
                .andExpect(status().isOk());

        // 窗内无赞助商素材 → 409 WINDOW_VIOLATION
        putDraft(ch, "req-" + p + "-d2", 1,
                segment(p + "s2", p + "neutral", T_1030, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p2", 2, 1))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("WINDOW_VIOLATION"))
                .andExpect(jsonPath("$.details.conflicts[0].assetSponsorKey").isEmpty());
    }

    // ---------- 多频道批量发布：全有或全无 ----------

    @Test
    void batchPublishSucceedsTogetherOrFailsAtomically() throws Exception {
        String p = prefix();
        String ch1 = newChannel(p, "1");
        String ch2 = newChannel(p, "2");
        createGrant(ch1, p + "nike", "NIKE");
        createGrant(ch2, p + "nike", "NIKE");
        createGrant(ch2, p + "adidas", "ADIDAS");
        registerWindowOk("NIKE", "req-" + p + "-w1", ch1, T_10, T_11);
        registerWindowOk("NIKE", "req-" + p + "-w2", ch2, T_10, T_11);

        putDraft(ch1, "req-" + p + "-d1", 0,
                segment(p + "s1", p + "nike", T_10, T_1030));
        putDraft(ch2, "req-" + p + "-d2", 0,
                segment(p + "s2", p + "nike", T_10, T_1020),
                segment(p + "s3", p + "nike", T_1020, T_11));

        Map<String, Object> batch = new LinkedHashMap<>();
        batch.put("requestId", "req-" + p + "-b1");
        batch.put("channels", List.of(
                Map.of("channelId", ch2, "draftVersion", 1, "expectedPublishedVersion", 0),
                Map.of("channelId", ch1, "draftVersion", 1, "expectedPublishedVersion", 0)));

        MvcResult ok = postJson("/api/business-days/" + DAY + "/publish", batch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.requestedChannelCount").value(2))
                .andExpect(jsonPath("$.publishedChannelCount").value(2))
                .andExpect(jsonPath("$.scheduledDurationMs").value(3600000))
                .andReturn();
        JsonNode okJson = readJson(ok);
        long id1 = okJson.get("channels").get(0).get("publicationId").asLong();
        long id2 = okJson.get("channels").get(1).get("publicationId").asLong();
        assertThat(id1).isNotEqualTo(id2);

        // 同参重放：返回相同 publicationId
        MvcResult replay = postJson("/api/business-days/" + DAY + "/publish", batch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedChannelCount").value(2))
                .andReturn();
        JsonNode replayJson = readJson(replay);
        List<Long> replayIds = List.of(
                replayJson.get("channels").get(0).get("publicationId").asLong(),
                replayJson.get("channels").get(1).get("publicationId").asLong());
        assertThat(replayIds).containsExactlyInAnyOrder(id1, id2);

        // 异参 409
        Map<String, Object> changed = new LinkedHashMap<>(batch);
        changed.put("requestId", "req-" + p + "-b1");
        changed.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 1, "expectedPublishedVersion", 0)));
        postJson("/api/business-days/" + DAY + "/publish", changed)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));

        // 第二轮：ch2 改排异赞助商 → 整次 409，ch1 也不得留下新版本
        putDraft(ch1, "req-" + p + "-d3", 1,
                segment(p + "s4", p + "nike", T_10, T_11));
        putDraft(ch2, "req-" + p + "-d4", 1,
                segment(p + "s5", p + "adidas", T_10, T_11));
        Map<String, Object> badBatch = new LinkedHashMap<>();
        badBatch.put("requestId", "req-" + p + "-b2");
        badBatch.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 2, "expectedPublishedVersion", 1),
                Map.of("channelId", ch2, "draftVersion", 2, "expectedPublishedVersion", 1)));
        postJson("/api/business-days/" + DAY + "/publish", badBatch)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].channelId").value(ch2));

        // 无部分更新：两频道当前生效发布仍为版本 1 的内容
        playout(ch1, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.segmentId").value(p + "s1"));
        playout(ch2, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.segmentId").value(p + "s3"));

        // 修正 ch2 后整批成功
        putDraft(ch2, "req-" + p + "-d5", 2,
                segment(p + "s6", p + "nike", T_10, T_11));
        Map<String, Object> goodBatch = new LinkedHashMap<>();
        goodBatch.put("requestId", "req-" + p + "-b3");
        goodBatch.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 2, "expectedPublishedVersion", 1),
                Map.of("channelId", ch2, "draftVersion", 3, "expectedPublishedVersion", 1)));
        postJson("/api/business-days/" + DAY + "/publish", goodBatch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedChannelCount").value(2));
    }

    // ---------- 撤销尚未开始/已开始的发布 ----------

    @Test
    void cancelPublicationBeforeStartReleasesSlotAndKeepsHits() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        createGrant(ch, p + "nike", "NIKE");
        registerWindowOk("NIKE", "req-" + p + "-w", ch, T_10, T_11);
        putDraft(ch, "req-" + p + "-d1", 0,
                segment(p + "s1", p + "nike", T_10, T_11));
        long publicationId = publishOk(ch, "req-" + p + "-p1", 1, 0);

        // 开播前撤销
        when(clock.millis()).thenReturn(OffsetDateTime.parse(T_10).toInstant().toEpochMilli() - 1);
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"))
                .andExpect(jsonPath("$.cancelRequestId").value("req-" + p + "-c"))
                // 命中历史保留
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1));

        // 占位已释放：播出回到无编排保底
        playout(ch, T_1030)
                .andExpect(jsonPath("$.source").value("FALLBACK"))
                .andExpect(jsonPath("$.reason").value("NO_PUBLISHED_SCHEDULE"));

        // 重放幂等
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));
        // 新 requestId 重复撤销 → 409
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + p + "-c2"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("PUBLICATION_ALREADY_CANCELLED"));

        // 撤销后可再发布新版本
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + p + "-p2", 1, 1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(2));
    }

