    @Test
    void emergencyOverrideEnforcesWindowsAndExistingSchedule() throws Exception {
        String p = prefix();
        String ch = newChannel(p, "1");
        long nikeGrant = createGrant(ch, p + "nike", "NIKE");
        long adidasGrant = createGrant(ch, p + "adidas", "ADIDAS");
        registerWindowOk("NIKE", "req-" + p + "-w", ch, T_1020, T_1040);

        // 异赞助商插播命中 NIKE 窗口 → 409
        createOverride(p + "ov-bad", ch, p + "adidas", adidasGrant, 5, T_1025, T_1035, "req-" + p + "-o1")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("WINDOW_VIOLATION"));
        // 失败不占键且未留下插播
        getJson("/api/emergency-overrides/" + p + "ov-bad").andExpect(status().isNotFound());

        // 同赞助商插播成功，响应带 sponsorKey
        createOverride(p + "ov-ok", ch, p + "nike", nikeGrant, 5, T_1025, T_1035, "req-" + p + "-o2")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value("NIKE"));

        // 另一异赞助商插播与 NIKE ACTIVE 插播相交 → SPONSOR_OVERLAP（无窗口也冲突）
        registerWindowOk("ADIDAS", "req-" + p + "-w2", ch,
                "2026-09-22T14:00:00.000+08:00", "2026-09-22T15:00:00.000+08:00");
        long adidasGrant2 = createGrant(ch, p + "adidas2", "ADIDAS");
        createOverride(p + "ov-a", ch, p + "adidas2", adidasGrant2, 3,
                "2026-09-22T14:00:00.000+08:00", "2026-09-22T14:20:00.000+08:00",
                "req-" + p + "-o3")
                .andExpect(status().isOk());
        createOverride(p + "ov-n", ch, p + "nike", nikeGrant, 3,
                "2026-09-22T14:10:00.000+08:00", "2026-09-22T14:30:00.000+08:00",
                "req-" + p + "-o4")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("WINDOW_VIOLATION"))
                .andExpect(jsonPath("$.details.conflicts[1].conflictType").value("SPONSOR_OVERLAP"));

        // 与已发布异赞助商节目冲突：先发布 ADIDAS 节目（窗口之外），再插播 NIKE 相交 → 409
        String ch2 = newChannel(p, "2");
        long adidasGrantCh2 = createGrant(ch2, p + "adidas", "ADIDAS");
        long nikeGrantCh2 = createGrant(ch2, p + "nike", "NIKE");
        putDraft(ch2, "req-" + p + "-d2", 0,
                segment(p + "s2", p + "adidas", T_10, T_11));
        publishOk(ch2, "req-" + p + "-p2", 1, 0);
        createOverride(p + "ov-x", ch2, p + "nike", nikeGrantCh2, 5, T_1020, T_1040,
                "req-" + p + "-o5")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("SPONSOR_OVERLAP"))
                .andExpect(jsonPath("$.details.conflicts[0].conflictAssetId").value(p + "adidas"));
        // 相邻不冲突
        createOverride(p + "ov-y", ch2, p + "nike", nikeGrantCh2, 5, T_11,
                "2026-09-22T11:20:00.000+08:00", "req-" + p + "-o6")
                .andExpect(status().isOk());
        assertThat(adidasGrantCh2).isPositive();
    }

