    // ---------- 辅助 ----------

    /** 创建频道（保底素材），返回频道 ID。 */
    private String newChannel(String p, String suffix) throws Exception {
        String channel = p + "ch" + suffix;
        postJson("/api/assets", Map.of("id", p + "fallback" + suffix, "durationMs", 30000))
                .andExpect(status().isOk());
        postJson("/api/channels",
                Map.of("id", channel, "fallbackAssetId", p + "fallback" + suffix))
                .andExpect(status().isOk());
        return channel;
    }

    /** 创建素材（可带赞助商）与全天授权，返回授权 ID。 */
    private long createGrant(String channel, String asset, String sponsorKey) throws Exception {
        Map<String, Object> assetBody = new LinkedHashMap<>();
        assetBody.put("id", asset);
        assetBody.put("durationMs", 3600000);
        if (sponsorKey != null) {
            assetBody.put("sponsorKey", sponsorKey);
        }
        postJson("/api/assets", assetBody).andExpect(status().isOk());
        MvcResult result = postJson("/api/grants", Map.of(
                        "channelId", channel, "assetId", asset,
                        "validFrom", GRANT_FROM, "validTo", GRANT_TO))
                .andExpect(status().isOk()).andReturn();
        return readJson(result).get("id").asLong();
    }

    private ResultActions registerWindow(String sponsor, String requestId, Map<String, Object> body)
            throws Exception {
        Map<String, Object> withId = new LinkedHashMap<>(body);
        withId.put("requestId", requestId);
        return postJson("/api/sponsors/" + sponsor + "/windows/" + DAY, withId);
    }

    private long registerWindowOk(String sponsor, String requestId, String channel,
                                  String start, String end) throws Exception {
        MvcResult result = registerWindow(sponsor, requestId,
                Map.of("start", start, "end", end, "channelIds", List.of(channel)))
                .andExpect(status().isOk()).andReturn();
        return readJson(result).get("id").asLong();
    }

    private static Map<String, Object> segment(String id, String assetId, String start, String end) {
        Map<String, Object> segment = new LinkedHashMap<>();
        segment.put("id", id);
        segment.put("assetId", assetId);
        segment.put("start", start);
        segment.put("end", end);
        return segment;
    }

    private void putDraft(String channel, String requestId, long expectedVersion,
                          Map<String, Object>... segments) throws Exception {
        List<Map<String, Object>> list = new ArrayList<>(List.of(segments));
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("requestId", requestId);
        body.put("expectedDraftVersion", expectedVersion);
        body.put("segments", list);
        putJson("/api/channels/" + channel + "/drafts/" + DAY, body).andExpect(status().isOk());
    }

    private static Map<String, Object> publishBody(String requestId, long draftVersion,
                                                   long expectedPublishedVersion) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("requestId", requestId);
        body.put("draftVersion", draftVersion);
        body.put("expectedPublishedVersion", expectedPublishedVersion);
        return body;
    }

    private long publishOk(String channel, String requestId, long draftVersion,
                           long expectedPublishedVersion) throws Exception {
        MvcResult result = postJson("/api/channels/" + channel + "/drafts/" + DAY + "/publish",
                        publishBody(requestId, draftVersion, expectedPublishedVersion))
                .andExpect(status().isOk()).andReturn();
        return readJson(result).get("publicationId").asLong();
    }

    private ResultActions createOverride(String key, String channel, String asset, long grantId,
                                         int priority, String start, String end, String requestId)
            throws Exception {
        return postJson("/api/emergency-overrides", Map.of(
                "requestId", requestId, "overrideKey", key, "channelId", channel,
                "assetId", asset, "grantId", grantId, "priority", priority,
                "start", start, "end", end));
    }

    private ResultActions playout(String channel, String at) throws Exception {
        return getJson("/api/channels/" + channel + "/playout", at);
    }

    private ResultActions postJson(String url, Object body) throws Exception {
        return mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(json(body)));
    }

    private ResultActions putJson(String url, Object body) throws Exception {
        return mvc.perform(put(url).contentType(MediaType.APPLICATION_JSON).content(json(body)));
    }

    private ResultActions getJson(String url) throws Exception {
        return mvc.perform(get(url));
    }

    private ResultActions getJson(String url, String at) throws Exception {
        return mvc.perform(get(url).param("at", at));
    }

    private String json(Object body) throws Exception {
        return objectMapper.writeValueAsString(body);
    }

    private JsonNode readJson(MvcResult result) throws Exception {
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private static String prefix() {
        return "s" + UUID.randomUUID().toString().replace("-", "").substring(0, 10) + "-";
    }

    private interface ThrowingSupplier {
        Integer get(int index) throws Exception;
    }

    private static List<Integer> runConcurrently(int threads, ThrowingSupplier action)
            throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<Integer>> futures = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            final int index = i;
            futures.add(pool.submit(() -> {
                ready.countDown();
                start.await(10, TimeUnit.SECONDS);
                return action.get(index);
            }));
        }
        ready.await(10, TimeUnit.SECONDS);
        start.countDown();
        List<Integer> results = new ArrayList<>();
        for (Future<Integer> future : futures) {
            results.add(future.get(30, TimeUnit.SECONDS));
        }
        pool.shutdownNow();
        return results;
    }

    // 防止未使用的导入被格式化误删：ZoneOffset 在时间语义注释中保留引用。
    @SuppressWarnings("unused")
    private static final ZoneOffset ZERO = ZoneOffset.UTC;
}

