package com.example.starter.playout;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * 赞助商排他冲突检测（纯逻辑，无数据库依赖）。
 *
 * <p>所有区间为 UTC 纪元毫秒、左闭右开 [start, end)。规则：</p>
 * <ul>
 *   <li>排他窗内只允许排入与窗口同赞助商（sponsorKey 相等）的素材；无赞助商素材（sponsorKey 为 null）
 *       或异赞助商素材命中窗口均为冲突；</li>
 *   <li>同一频道最终编排中，两个赞助商键非空且不相等的生效素材时段相交即为冲突；
 *       同赞助商不同素材、任一方无赞助商均允许并存。</li>
 * </ul>
 */
public final class SponsorExclusivity {

    private SponsorExclusivity() {
    }

    /** 参与判定的素材时段（发布候选片段、既有发布片段或 ACTIVE 紧急插播）。 */
    public record Item(String id, String assetId, String sponsorKey,
                       long startMs, long endMs, boolean fresh) {
    }

    /** 命中频道的生效排他窗。 */
    public record Window(long id, String sponsorKey, long version, long startMs, long endMs) {
    }

    /** 半开区间。 */
    public record Interval(long startMs, long endMs) {
        public long durationMs() {
            return endMs - startMs;
        }
    }

    /** 结构化冲突明细；未命中的字段为 null。 */
    public record Conflict(String channelId, long startMs, long endMs, long durationMs,
                           String conflictType, String windowSponsorKey, Long windowId,
                           Long windowVersion, String segmentId, String assetId,
                           String assetSponsorKey, String conflictAssetId,
                           String conflictSponsorKey) {
    }

    /** 两个半开区间是否相交（相邻 start == end 不算相交）。 */
    public static boolean overlaps(long aStart, long aEnd, long bStart, long bEnd) {
        return aStart < bEnd && bStart < aEnd;
    }

    /**
     * 评估单个频道的完整最终编排。fresh=false 的既有项之间冲突属历史状态，不随本次操作裁决，
     * 仅返回至少涉及一个 fresh 项的冲突。结果按开始时间、类型、双方素材键排序，保证稳定。
     */
    public static List<Conflict> evaluateChannel(String channelId, List<Item> items,
                                                 List<Window> windows) {
        List<Conflict> conflicts = new ArrayList<>();

        // 素材 × 命中排他窗：素材赞助商必须与窗口赞助商相同。
        for (Item item : items) {
            if (!item.fresh()) {
                continue;
            }
            for (Window window : windows) {
                if (overlaps(item.startMs(), item.endMs(), window.startMs(), window.endMs())
                        && !window.sponsorKey().equals(item.sponsorKey())) {
                    long s = Math.max(item.startMs(), window.startMs());
                    long e = Math.min(item.endMs(), window.endMs());
                    conflicts.add(new Conflict(channelId, s, e, e - s, "WINDOW_VIOLATION",
                            window.sponsorKey(), window.id(), window.version(),
                            item.id(), item.assetId(), item.sponsorKey(), null, null));
                }
            }
        }

        // 素材两两之间：赞助商键非空且不相等即冲突；保留至少一方为 fresh 的冲突。
        for (int i = 0; i < items.size(); i++) {
            for (int j = i + 1; j < items.size(); j++) {
                Item a = items.get(i);
                Item b = items.get(j);
                if (!a.fresh() && !b.fresh()) {
                    continue;
                }
                if (a.sponsorKey() == null || b.sponsorKey() == null) {
                    continue;
                }
                if (a.sponsorKey().equals(b.sponsorKey())) {
                    continue;
                }
                if (!overlaps(a.startMs(), a.endMs(), b.startMs(), b.endMs())) {
                    continue;
                }
                long s = Math.max(a.startMs(), b.startMs());
                long e = Math.min(a.endMs(), b.endMs());
                conflicts.add(new Conflict(channelId, s, e, e - s, "SPONSOR_OVERLAP",
                        null, null, null,
                        a.id(), a.assetId(), a.sponsorKey(), b.assetId(), b.sponsorKey()));
            }
        }

        conflicts.sort(Comparator.comparingLong(Conflict::startMs)
                .thenComparing(Conflict::conflictType)
                .thenComparing(c -> c.segmentId() == null ? "" : c.segmentId())
                .thenComparing(c -> c.windowId() == null ? Long.MIN_VALUE : c.windowId())
                .thenComparing(c -> c.conflictAssetId() == null ? "" : c.conflictAssetId()));
        return conflicts;
    }

    /** 区间并集（相交或相邻即合并），输出按起点排序且互不相交。 */
    public static List<Interval> union(List<Interval> intervals) {
        List<Interval> sorted = intervals.stream()
                .filter(v -> v.endMs() > v.startMs())
                .sorted(Comparator.comparingLong(Interval::startMs)
                        .thenComparingLong(Interval::endMs))
                .toList();
        List<Interval> merged = new ArrayList<>();
        for (Interval v : sorted) {
            if (merged.isEmpty() || v.startMs() > merged.get(merged.size() - 1).endMs()) {
                merged.add(v);
            } else {
                Interval last = merged.remove(merged.size() - 1);
                merged.add(new Interval(last.startMs(), Math.max(last.endMs(), v.endMs())));
            }
        }
        return merged;
    }

    /** 从区间 [start, end) 中扣除 blockers 的并集，返回剩余的互不相交区间。 */
    public static List<Interval> subtract(long start, long end, List<Interval> blockers) {
        List<Interval> union = union(blockers);
        List<Interval> remain = new ArrayList<>();
        long cursor = start;
        for (Interval blocker : union) {
            if (blocker.endMs() <= cursor) {
                continue;
            }
            if (blocker.startMs() >= end) {
                break;
            }
            if (blocker.startMs() > cursor) {
                remain.add(new Interval(cursor, Math.min(blocker.startMs(), end)));
            }
            cursor = Math.max(cursor, blocker.endMs());
            if (cursor >= end) {
                break;
            }
        }
        if (cursor < end) {
            remain.add(new Interval(cursor, end));
        }
        return remain;
    }
}

