package com.example.starter.playout;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.ResultActions;

import java.time.Clock;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 播出赞助排他 H2（MODE=MySQL）真实数据库端到端测试：窗口登记、草稿发布（单/多频道）、
 * 紧急插播排他校验、快照固化、发布撤销、诊断查询、幂等与并发提交顺序裁决。
 * 每个用例的赞助商键带随机前缀，窗口版本与列表互不干扰；数据用独立命名隔离。
 */
@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
class SponsorExclusivityApiTest {

    private static final String DAY = "2026-09-22";
    private static final String GRANT_FROM = "2026-09-22T00:00:00.000+08:00";
    private static final String GRANT_TO = "2026-09-23T00:00:00.000+08:00";
    private static final String T_09 = "2026-09-22T09:00:00.000+08:00";
    private static final String T_0930 = "2026-09-22T09:30:00.000+08:00";
    private static final String T_10 = "2026-09-22T10:00:00.000+08:00";
    private static final String T_1010 = "2026-09-22T10:10:00.000+08:00";
    private static final String T_1020 = "2026-09-22T10:20:00.000+08:00";
    private static final String T_1025 = "2026-09-22T10:25:00.000+08:00";
    private static final String T_1030 = "2026-09-22T10:30:00.000+08:00";
    private static final String T_1035 = "2026-09-22T10:35:00.000+08:00";
    private static final String T_1040 = "2026-09-22T10:40:00.000+08:00";
    private static final String T_11 = "2026-09-22T11:00:00.000+08:00";
    private static final String T_14 = "2026-09-22T14:00:00.000+08:00";
    private static final String T_1410 = "2026-09-22T14:10:00.000+08:00";
    private static final String T_1420 = "2026-09-22T14:20:00.000+08:00";
    private static final String T_1430 = "2026-09-22T14:30:00.000+08:00";
    private static final String T_15 = "2026-09-22T15:00:00.000+08:00";

    @Autowired
    private MockMvc mvc;

    @Autowired
    private ObjectMapper objectMapper;

    /** 可控时钟：撤销发布的“尚未开始”判定依赖当前时间。 */
    @MockitoBean
    private Clock clock;

    // ---------- 素材 sponsorKey 透传 ----------

    @Test
    void assetCarriesSponsorKeyAndNullMeansNoSponsor() throws Exception {
        String p = prefix();
        postJson("/api/assets", Map.of("id", p + "a", "durationMs", 1000, "sponsorKey", p + "NIKE"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value(p + "NIKE"));
        postJson("/api/assets", Map.of("id", p + "b", "durationMs", 1000))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").isEmpty());
    }

    // ---------- 窗口登记主流程与 422 分支 ----------

    @Test
    void registerWindowSuccessCountsDurationAndOverlapRules() throws Exception {
        Ctx c = newCtx();
        String ch1 = c.channel("1");
        String ch2 = c.channel("2");

        // 主流程：版本 1，返回实际时长与频道数量
        MvcResult result = registerWindow(c.nike, "req-" + c.p + "-w1",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch2, ch1)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value(c.nike))
                .andExpect(jsonPath("$.businessDay").value(DAY))
                .andExpect(jsonPath("$.version").value(1))
                .andExpect(jsonPath("$.durationMs").value(3600000))
                .andExpect(jsonPath("$.channelCount").value(2))
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andReturn();
        long windowId = readJson(result).get("id").asLong();

        // 明细：频道排序确定、时间毫秒精度
        getJson("/api/sponsor-windows/" + windowId)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.channelIds[0]").value(ch1))
                .andExpect(jsonPath("$.channelIds[1]").value(ch2))
                .andExpect(jsonPath("$.start").value(T_10))
                .andExpect(jsonPath("$.end").value(T_11));

        // 同赞助商同频道窗口重叠 → 422（另一频道不重叠也不行）
        registerWindow(c.nike, "req-" + c.p + "-w2",
                Map.of("start", T_1030, "end", "2026-09-22T11:30:00.000+08:00",
                        "channelIds", List.of(ch2)))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("SPONSOR_WINDOW_OVERLAP"));

        // 相邻（左闭右开）合法
        registerWindow(c.nike, "req-" + c.p + "-w3",
                Map.of("start", T_11, "end", "2026-09-22T12:00:00.000+08:00",
                        "channelIds", List.of(ch1)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));

        // 不同赞助商同频道同时段允许并存
        registerWindow(c.adidas, "req-" + c.p + "-w4",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch1)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1));

        // 422：频道集合为空
        registerWindow(c.nike, "req-" + c.p + "-empty",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of()))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("WINDOW_CHANNELS_EMPTY"));

        // 422：时间非法（终点 <= 起点）
        registerWindow(c.nike, "req-" + c.p + "-bad1",
                Map.of("start", T_11, "end", T_10, "channelIds", List.of(ch1)))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("WINDOW_INVALID_TIME"));

        // 422：跨运营日
        registerWindow(c.nike, "req-" + c.p + "-bad2",
                Map.of("start", "2026-09-22T23:30:00.000+08:00",
                        "end", "2026-09-23T00:30:00.000+08:00",
                        "channelIds", List.of(ch1)))
                .andExpect(status().isUnprocessableEntity());

        // 404：频道不存在
        registerWindow(c.nike, "req-" + c.p + "-bad3",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(c.p + "ghost")))
                .andExpect(status().isNotFound());
    }

    // ---------- 窗口登记幂等：重放、异参 409、失败不占键 ----------

    @Test
    void windowRegistrationIdempotency() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        Map<String, Object> body = Map.of("start", T_10, "end", T_11,
                "channelIds", List.of(ch));

        MvcResult first = registerWindow(c.nike, "req-" + c.p + "-idem", body)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1))
                .andReturn();
        long firstId = readJson(first).get("id").asLong();

        // 同参重放：返回首次结果，不产生新版本
        MvcResult replay = registerWindow(c.nike, "req-" + c.p + "-idem", body)
                .andExpect(status().isOk()).andReturn();
        assertThat(readJson(replay).get("id").asLong()).isEqualTo(firstId);

        // 异参 409
        registerWindow(c.nike, "req-" + c.p + "-idem",
                Map.of("start", T_1020, "end", T_11, "channelIds", List.of(ch)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));

        // 失败不占键：先用空频道集合失败，再用同 requestId 成功
        registerWindow(c.nike, "req-" + c.p + "-retry",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of()))
                .andExpect(status().isUnprocessableEntity());
        registerWindow(c.nike, "req-" + c.p + "-retry",
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));
    }

    // ---------- 窗口删除与列表 ----------

    @Test
    void cancelWindowKeepsHistoryAndIsIdempotent() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        long windowId = registerWindowOk(c.nike, "req-" + c.p + "-w", ch, T_10, T_11);

        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"))
                .andExpect(jsonPath("$.cancelRequestId").value("req-" + c.p + "-c"))
                .andExpect(jsonPath("$.cancelledAt").isNotEmpty());
        // 重放
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));
        // 新请求重复删除 → 409
        postJson("/api/sponsor-windows/" + windowId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c2"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_WINDOW_ALREADY_CANCELLED"));
        // 404
        postJson("/api/sponsor-windows/999999/cancel", Map.of("requestId", "req-" + c.p + "-x"))
                .andExpect(status().isNotFound());

        // 列表含已删除窗口，按版本排序
        getJson("/api/sponsors/" + c.nike + "/windows/" + DAY)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].id").value(windowId))
                .andExpect(jsonPath("$[0].status").value("CANCELLED"));
    }

    // ---------- 发布排他主流程、409 明细与快照固化 ----------

    @Test
    void publishEnforcesWindowAndFreezesHitVersion() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        long nikeGrant = c.grant(ch, "nike", c.nike);
        long adidasGrant = c.grant(ch, "adidas", c.adidas);
        assertThat(nikeGrant).isNotEqualTo(adidasGrant);

        // NIKE 窗口 10:00-11:00
        long windowId = registerWindowOk(c.nike, "req-" + c.p + "-w", ch, T_10, T_11);

        // 异赞助商片段在窗内 → 409，返回频道、相交时段与冲突素材
        putDraft(ch, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "adidas", T_1020, T_1040));
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + c.p + "-p1", 1, 0))
                .andExpect(status().isConflict())
