                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));
        // 新 requestId 重复撤销 → 409
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c2"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("PUBLICATION_ALREADY_CANCELLED"));

        // 撤销后可再发布新版本
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + c.p + "-p2", 1, 1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(2));
    }

