    // ---------- 窗口登记幂等：重放、异参 409、失败不占键 ----------

    @Test
    void windowRegistrationIdempotency() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        Map<String, Object> body = Map.of("start", T_10, "end", T_11,
                "channelIds", List.of(ch));

        MvcResult first = registerWindow(c.nike, "req-" + c.p + "-idem", body)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1))
