                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1));
    }

    @Test
    void publishRejectsUnsponsoredAssetInsideWindowAndAdjacentIsAllowed() throws Exception {
        Ctx c = newCtx();
