    // ---------- 多频道批量发布：全有或全无 ----------

    @Test
    void batchPublishSucceedsTogetherOrFailsAtomically() throws Exception {
        Ctx c = newCtx();
        String ch1 = c.channel("1");
        String ch2 = c.channel("2");
        c.grant(ch1, "nike", c.nike);
        c.grant(ch2, "nike", c.nike);
        c.grant(ch2, "adidas", c.adidas);
        registerWindowOk(c.nike, "req-" + c.p + "-w1", ch1, T_10, T_11);
        registerWindowOk(c.nike, "req-" + c.p + "-w2", ch2, T_10, T_11);

        putDraft(ch1, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "nike", T_10, T_1030));
        putDraft(ch2, "req-" + c.p + "-d2", 0,
                segment(c.p + "s2", c.p + "nike", T_10, T_1020),
                segment(c.p + "s3", c.p + "nike", T_1020, T_11));

        Map<String, Object> batch = new LinkedHashMap<>();
        batch.put("requestId", "req-" + c.p + "-b1");
        batch.put("channels", List.of(
                Map.of("channelId", ch2, "draftVersion", 1, "expectedPublishedVersion", 0),
                Map.of("channelId", ch1, "draftVersion", 1, "expectedPublishedVersion", 0)));

        MvcResult ok = postJson("/api/business-days/" + DAY + "/publish", batch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.requestedChannelCount").value(2))
                .andExpect(jsonPath("$.publishedChannelCount").value(2))
                .andExpect(jsonPath("$.scheduledDurationMs").value(3600000))
                .andReturn();
        JsonNode okJson = readJson(ok);
        List<Long> firstIds = new ArrayList<>();
        for (JsonNode channel : okJson.get("channels")) {
            firstIds.add(channel.get("publicationId").asLong());
        }
        assertThat(firstIds).hasSize(2).doesNotHaveDuplicates();

        // 同参重放：返回相同 publicationId
        MvcResult replay = postJson("/api/business-days/" + DAY + "/publish", batch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedChannelCount").value(2))
                .andReturn();
        List<Long> replayIds = new ArrayList<>();
        for (JsonNode channel : readJson(replay).get("channels")) {
            replayIds.add(channel.get("publicationId").asLong());
        }
        assertThat(replayIds).containsExactlyInAnyOrderElementsOf(firstIds);

        // 异参 409
        Map<String, Object> changed = new LinkedHashMap<>();
        changed.put("requestId", "req-" + c.p + "-b1");
        changed.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 1, "expectedPublishedVersion", 0)));
        postJson("/api/business-days/" + DAY + "/publish", changed)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("REQUEST_ID_CONFLICT"));

        // 第二轮：ch2 改排异赞助商 → 整次 409，ch1 也不得留下新版本
        putDraft(ch1, "req-" + c.p + "-d3", 1,
                segment(c.p + "s4", c.p + "nike", T_10, T_11));
        putDraft(ch2, "req-" + c.p + "-d4", 1,
                segment(c.p + "s5", c.p + "adidas", T_10, T_11));
        Map<String, Object> badBatch = new LinkedHashMap<>();
        badBatch.put("requestId", "req-" + c.p + "-b2");
        badBatch.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 2, "expectedPublishedVersion", 1),
                Map.of("channelId", ch2, "draftVersion", 2, "expectedPublishedVersion", 1)));
        postJson("/api/business-days/" + DAY + "/publish", badBatch)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].channelId").value(ch2));

        // 无部分更新：两频道当前生效发布仍为版本 1 的内容
        playout(ch1, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.segmentId").value(c.p + "s1"));
        playout(ch2, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.segmentId").value(c.p + "s3"));

        // 修正 ch2 后整批成功
        putDraft(ch2, "req-" + c.p + "-d5", 2,
                segment(c.p + "s6", c.p + "nike", T_10, T_11));
        Map<String, Object> goodBatch = new LinkedHashMap<>();
        goodBatch.put("requestId", "req-" + c.p + "-b3");
        goodBatch.put("channels", List.of(
                Map.of("channelId", ch1, "draftVersion", 2, "expectedPublishedVersion", 1),
                Map.of("channelId", ch2, "draftVersion", 3, "expectedPublishedVersion", 1)));
        postJson("/api/business-days/" + DAY + "/publish", goodBatch)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedChannelCount").value(2));
    }

    // ---------- 撤销尚未开始/已开始的发布 ----------

    @Test
    void cancelPublicationBeforeStartReleasesSlotAndKeepsHits() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        c.grant(ch, "nike", c.nike);
        registerWindowOk(c.nike, "req-" + c.p + "-w", ch, T_10, T_11);
        putDraft(ch, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "nike", T_10, T_11));
        long publicationId = publishOk(ch, "req-" + c.p + "-p1", 1, 0);

        // 开播前撤销
        when(clock.millis()).thenReturn(OffsetDateTime.parse(T_10).toInstant().toEpochMilli() - 1);
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"))
                .andExpect(jsonPath("$.cancelRequestId").value("req-" + c.p + "-c"))
                // 命中历史保留
                .andExpect(jsonPath("$.sponsorHits[0].windowVersion").value(1));

        // 占位已释放：播出回到无编排保底
        playout(ch, T_1030)
                .andExpect(jsonPath("$.source").value("FALLBACK"))
                .andExpect(jsonPath("$.reason").value("NO_PUBLISHED_SCHEDULE"));

        // 重放幂等
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("CANCELLED"));
        // 新 requestId 重复撤销 → 409
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c2"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("PUBLICATION_ALREADY_CANCELLED"));

        // 撤销后可再发布新版本
        postJson("/api/channels/" + ch + "/drafts/" + DAY + "/publish",
                        publishBody("req-" + c.p + "-p2", 1, 1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.publishedVersion").value(2));
    }

    @Test
    void cancelPublicationAfterStartIsRejected() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        c.grant(ch, "nike", c.nike);
        putDraft(ch, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "nike", T_10, T_11));
        long publicationId = publishOk(ch, "req-" + c.p + "-p1", 1, 0);

        // 已开播 → 409，只能走紧急插播流程
        when(clock.millis()).thenReturn(OffsetDateTime.parse(T_10).toInstant().toEpochMilli());
        postJson("/api/publications/" + publicationId + "/cancel",
                Map.of("requestId", "req-" + c.p + "-c"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("PUBLICATION_ALREADY_STARTED"));
        getJson("/api/publications/" + publicationId)
                .andExpect(jsonPath("$.status").value("PUBLISHED"));
    }

    // ---------- 紧急插播的排他校验 ----------

    @Test
    void emergencyOverrideEnforcesWindowsAndExistingSchedule() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        long nikeGrant = c.grant(ch, "nike", c.nike);
        long adidasGrant = c.grant(ch, "adidas", c.adidas);
        registerWindowOk(c.nike, "req-" + c.p + "-w", ch, T_1020, T_1040);

        // 异赞助商插播命中 NIKE 窗口 → 409
        createOverride(c.p + "ov-bad", ch, c.p + "adidas", adidasGrant, 5, T_1025, T_1035,
                "req-" + c.p + "-o1")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("SPONSOR_EXCLUSIVITY_CONFLICT"))
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("WINDOW_VIOLATION"));
        // 失败不占键且未留下插播
        getJson("/api/emergency-overrides/" + c.p + "ov-bad").andExpect(status().isNotFound());

        // 同赞助商插播成功，响应带 sponsorKey
        createOverride(c.p + "ov-ok", ch, c.p + "nike", nikeGrant, 5, T_1025, T_1035,
                "req-" + c.p + "-o2")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sponsorKey").value(c.nike));

        // 异赞助商插播与 NIKE ACTIVE 插播相交：不同优先级避开同优先级旧规则，
        // 同时命中 ADIDAS 窗口 → SPONSOR_OVERLAP 与 WINDOW_VIOLATION 两种冲突
        registerWindowOk(c.adidas, "req-" + c.p + "-w2", ch, T_14, T_15);
        long adidasGrant2 = c.grant(ch, "adidas2", c.adidas);
        createOverride(c.p + "ov-a", ch, c.p + "adidas2", adidasGrant2, 3, T_14, T_1420,
                "req-" + c.p + "-o3")
                .andExpect(status().isOk());
        createOverride(c.p + "ov-n", ch, c.p + "nike", nikeGrant, 4, T_1410, T_1430,
                "req-" + c.p + "-o4")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("SPONSOR_OVERLAP"))
                .andExpect(jsonPath("$.details.conflicts[1].conflictType").value("WINDOW_VIOLATION"));

        // 与已发布异赞助商节目冲突：先发布 ADIDAS 节目（无窗口），再插播 NIKE 相交 → 409
        String ch2 = c.channel("2");
        long nikeGrantCh2 = c.grant(ch2, "nike", c.nike);
        c.grant(ch2, "adidas", c.adidas);
        putDraft(ch2, "req-" + c.p + "-d2", 0,
                segment(c.p + "s2", c.p + "adidas", T_10, T_11));
        publishOk(ch2, "req-" + c.p + "-p2", 1, 0);
        createOverride(c.p + "ov-x", ch2, c.p + "nike", nikeGrantCh2, 5, T_1020, T_1040,
                "req-" + c.p + "-o5")
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.details.conflicts[0].conflictType").value("SPONSOR_OVERLAP"))
                .andExpect(jsonPath("$.details.conflicts[0].conflictAssetId").value(c.p + "adidas"));
        // 相邻不冲突
        createOverride(c.p + "ov-y", ch2, c.p + "nike", nikeGrantCh2, 5, T_11,
                "2026-09-22T11:20:00.000+08:00", "req-" + c.p + "-o6")
                .andExpect(status().isOk());
    }

    // ---------- 诊断查询 ----------

    @Test
    void diagnosticsReportActualRequiredAndDiffDurations() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        c.grant(ch, "adidas", c.adidas);
        // 先排入 ADIDAS 10:00-10:20，再登记 NIKE 窗口 10:00-11:00（提交顺序：发布先于窗口）
        putDraft(ch, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "adidas", T_10, T_1020));
        publishOk(ch, "req-" + c.p + "-p1", 1, 0);
        registerWindowOk(c.nike, "req-" + c.p + "-w", ch, T_10, T_11);

        getJson("/api/channels/" + ch + "/business-days/" + DAY + "/sponsor-diagnostics")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].sponsorKey").value(c.nike))
                .andExpect(jsonPath("$[0].windowDurationMs").value(3600000))
                .andExpect(jsonPath("$[0].ownScheduledDurationMs").value(0))
                .andExpect(jsonPath("$[0].otherScheduledDurationMs").value(1200000))
                .andExpect(jsonPath("$[0].uncoveredDurationMs").value(2400000))
                .andExpect(jsonPath("$[0].conflicts[0].assetSponsorKey").value(c.adidas));

        // 只读：片段时间内状态未改
        playout(ch, T_1010).andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.assetId").value(c.p + "adidas"));
    }

    // ---------- 并发：窗口登记串行化 ----------

    @Test
    void concurrentOverlappingWindowRegistrationsOnlyOneWins() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");

        List<Integer> statuses = runConcurrently(2, i -> registerWindow(c.nike,
                "req-" + c.p + "-w" + i,
                Map.of("start", T_10, "end", T_11, "channelIds", List.of(ch)))
                .andReturn().getResponse().getStatus());

        assertThat(statuses).containsExactlyInAnyOrder(200, 422);
        // 只有一个 ACTIVE 窗口
        JsonNode list = readJson(getJson("/api/sponsors/" + c.nike + "/windows/" + DAY).andReturn());
        assertThat(list).hasSize(1);
        assertThat(list.get(0).get("status").asText()).isEqualTo("ACTIVE");
    }

    // ---------- 并发：窗口登记与异赞助紧急插播按提交顺序裁决 ----------

    @Test
    void concurrentWindowAndOverrideAreSerializedWithoutDeadlock() throws Exception {
        Ctx c = newCtx();
        String ch = c.channel("1");
        long adidasGrant = c.grant(ch, "adidas", c.adidas);

        List<Integer> statuses = runConcurrently(2, i -> {
            if (i == 0) {
                return registerWindow(c.nike, "req-" + c.p + "-w",
                        Map.of("start", T_1020, "end", T_1040, "channelIds", List.of(ch)))
                        .andReturn().getResponse().getStatus();
            }
            return createOverride(c.p + "ov-race", ch, c.p + "adidas", adidasGrant, 5,
                    T_1025, T_1035, "req-" + c.p + "-o")
                    .andReturn().getResponse().getStatus();
        });

        // 窗口登记总能成功；插播在窗口先提交时 409，插播先提交时 200（合法的提交顺序结果）
        assertThat(statuses.get(0)).isEqualTo(200);
        assertThat(statuses.get(1)).isIn(200, 409);
        if (statuses.get(1) == 409) {
            getJson("/api/emergency-overrides/" + c.p + "ov-race").andExpect(status().isNotFound());
        } else {
            getJson("/api/emergency-overrides/" + c.p + "ov-race")
                    .andExpect(jsonPath("$.status").value("ACTIVE"));
        }
    }

    // ---------- 并发：同 expectedPublishedVersion 的批量发布只有一方成功 ----------

    @Test
    void concurrentBatchPublishesSameVersionOnlyOneWins() throws Exception {
        Ctx c = newCtx();
        String ch1 = c.channel("1");
        String ch2 = c.channel("2");
        c.grant(ch1, "nike", c.nike);
        c.grant(ch2, "nike", c.nike);
        putDraft(ch1, "req-" + c.p + "-d1", 0,
                segment(c.p + "s1", c.p + "nike", T_10, T_11));
        putDraft(ch2, "req-" + c.p + "-d2", 0,
                segment(c.p + "s2", c.p + "nike", T_10, T_11));

        List<Integer> statuses = runConcurrently(2, i -> {
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("requestId", "req-" + c.p + "-b" + i);
            body.put("channels", List.of(
                    Map.of("channelId", ch1, "draftVersion", 1, "expectedPublishedVersion", 0),
                    Map.of("channelId", ch2, "draftVersion", 1, "expectedPublishedVersion", 0)));
            return postJson("/api/business-days/" + DAY + "/publish", body)
                    .andReturn().getResponse().getStatus();
        });

        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
        // 无部分更新：两频道各只有一条生效发布
        playout(ch1, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"));
        playout(ch2, T_1030).andExpect(jsonPath("$.source").value("PROGRAM"));
    }

    // ---------- 辅助 ----------

    /** 单测试上下文：随机前缀、隔离赞助商键与频道/素材/授权工厂。 */
    private final class Ctx {
        private final String p = prefix();
        private final String nike = p + "NIKE";
        private final String adidas = p + "ADIDAS";

        /** 创建频道（保底素材），返回频道 ID。 */
        private String channel(String suffix) throws Exception {
            String channel = p + "ch" + suffix;
            asset(p + "fallback" + suffix, null, 30000L);
            postJson("/api/channels",
                    Map.of("id", channel, "fallbackAssetId", p + "fallback" + suffix))
                    .andExpect(status().isOk());
            return channel;
        }

        /** 创建素材（默认 1 小时），已存在则跳过（跨频道复用素材）。 */
        private void asset(String id, String sponsorKey) throws Exception {
            asset(id, sponsorKey, 3600000L);
        }

        private void asset(String id, String sponsorKey, long durationMs) throws Exception {
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("id", id);
            body.put("durationMs", durationMs);
            if (sponsorKey != null) {
                body.put("sponsorKey", sponsorKey);
            }
            int status = postJson("/api/assets", body).andReturn().getResponse().getStatus();
            assertThat(status).isIn(200, 409);
        }

        /** 为频道创建素材（带赞助商）与全天授权，返回授权 ID。 */
        private long grant(String channel, String assetSuffix, String sponsorKey) throws Exception {
            String assetId = p + assetSuffix;
            asset(assetId, sponsorKey);
            return grantExisting(channel, assetId);
        }

        /** 对已存在素材在指定频道创建全天授权。 */
        private long grantExisting(String channel, String assetId) throws Exception {
            MvcResult result = postJson("/api/grants", Map.of(
                            "channelId", channel, "assetId", assetId,
                            "validFrom", GRANT_FROM, "validTo", GRANT_TO))
                    .andExpect(status().isOk()).andReturn();
            return readJson(result).get("id").asLong();
        }
    }

    private Ctx newCtx() {
        return new Ctx();
    }

    private ResultActions registerWindow(String sponsor, String requestId, Map<String, Object> body)
            throws Exception {
        Map<String, Object> withId = new LinkedHashMap<>(body);
        withId.put("requestId", requestId);
        return postJson("/api/sponsors/" + sponsor + "/windows/" + DAY, withId);
    }

    private long registerWindowOk(String sponsor, String requestId, String channel,
                                  String start, String end) throws Exception {
        MvcResult result = registerWindow(sponsor, requestId,
                Map.of("start", start, "end", end, "channelIds", List.of(channel)))
                .andExpect(status().isOk()).andReturn();
        return readJson(result).get("id").asLong();
    }

    private static Map<String, Object> segment(String id, String assetId, String start, String end) {
        Map<String, Object> segment = new LinkedHashMap<>();
        segment.put("id", id);
        segment.put("assetId", assetId);
        segment.put("start", start);
        segment.put("end", end);
        return segment;
    }

    @SafeVarargs
    private final void putDraft(String channel, String requestId, long expectedVersion,
                                Map<String, Object>... segments) throws Exception {
        List<Map<String, Object>> list = new ArrayList<>(List.of(segments));
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("requestId", requestId);
        body.put("expectedDraftVersion", expectedVersion);
        body.put("segments", list);
        putJson("/api/channels/" + channel + "/drafts/" + DAY, body).andExpect(status().isOk());
    }

    private static Map<String, Object> publishBody(String requestId, long draftVersion,
                                                   long expectedPublishedVersion) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("requestId", requestId);
        body.put("draftVersion", draftVersion);
        body.put("expectedPublishedVersion", expectedPublishedVersion);
        return body;
    }

    private long publishOk(String channel, String requestId, long draftVersion,
                           long expectedPublishedVersion) throws Exception {
        MvcResult result = postJson("/api/channels/" + channel + "/drafts/" + DAY + "/publish",
                        publishBody(requestId, draftVersion, expectedPublishedVersion))
                .andExpect(status().isOk()).andReturn();
        return readJson(result).get("publicationId").asLong();
    }

    private ResultActions createOverride(String key, String channel, String asset, long grantId,
                                         int priority, String start, String end, String requestId)
            throws Exception {
        return postJson("/api/emergency-overrides", Map.of(
                "requestId", requestId, "overrideKey", key, "channelId", channel,
                "assetId", asset, "grantId", grantId, "priority", priority,
                "start", start, "end", end));
    }

    private ResultActions playout(String channel, String at) throws Exception {
        return getUrl("/api/channels/" + channel + "/playout?at=" + at);
    }

    private ResultActions postJson(String url, Object body) throws Exception {
        return mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(json(body)));
    }

    private ResultActions putJson(String url, Object body) throws Exception {
        return mvc.perform(put(url).contentType(MediaType.APPLICATION_JSON).content(json(body)));
    }

    private ResultActions getJson(String url) throws Exception {
        return getUrl(url);
    }

    private ResultActions getUrl(String url) throws Exception {
        return mvc.perform(get(url));
    }

    private String json(Object body) throws Exception {
        return objectMapper.writeValueAsString(body);
    }

    private JsonNode readJson(MvcResult result) throws Exception {
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private static String prefix() {
        return "s" + UUID.randomUUID().toString().replace("-", "").substring(0, 10) + "-";
    }

    private interface ThrowingSupplier {
        Integer get(int index) throws Exception;
    }

    private static List<Integer> runConcurrently(int threads, ThrowingSupplier action)
            throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<Integer>> futures = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            final int index = i;
            futures.add(pool.submit(() -> {
                ready.countDown();
                start.await(10, TimeUnit.SECONDS);
                return action.get(index);
            }));
        }
        ready.await(10, TimeUnit.SECONDS);
        start.countDown();
        List<Integer> results = new ArrayList<>();
        for (Future<Integer> future : futures) {
            results.add(future.get(30, TimeUnit.SECONDS));
        }
        pool.shutdownNow();
        return results;
    }
}

